sections/article-template.liquid:
{%- liquid
  assign number_of_comments = article.comments_count
  if comment.status == 'pending'
    assign number_of_comments = article.comments_count | plus: 1
  endif
-%}

{{ 'lovenspa-article.css' | asset_url | stylesheet_tag }}
{%- render 'breadcrumbs' -%}

{%- if section.settings.blog_show_tags and article.tags.size > 0 -%}
  <div class="article-tag__wrapper">
    {%- for tag in article.tags -%}
      {% if tag contains "_" %}{%- assign tag_starts_with = tag | slice: 0 -%}{% if tag_starts_with == "_" %}{% if tag_count %}{%- assign tag_count = tag_count | minus: 1 | at_least: 0 -%}{% endif %}{% continue %}{% endif %}{% endif %}
      <a href="{{ blog.url }}/tagged/{{ tag | handle }}" class="article-tag">{{ tag }}</a>
    {%- endfor -%}
  </div>
{%- endif -%}

<header class="section-header article-page-header">
  <h1 class="section-header__title article-page-header__title">{{ article.title }}</h1>

  <div class="article__sub-meta">
    {%- if section.settings.blog_show_comments and article.comments_count > 0 -%}
      <span>
        <a href="{{ article.url }}#comments" class="js-no-transition">
          {{ 'blogs.comments.with_count' | t: count: article.comments_count }}
        </a>
      </span>
    {%- endif -%}
    {%- if section.settings.blog_show_date -%}
      <span class="article__sub-meta-date">{{ article.published_at | time_tag: format: 'month_day_year' }}</span>
    {%- endif -%}
    {%- if section.settings.blog_show_author -%}
      <span>by {{ article.author }}</span>
    {%- endif -%}
  </div>
</header>

{%- comment -%} Love'nSpa : image à la une en tête d'article si le contenu n'a pas sa propre image {%- endcomment -%}
{%- liquid
  assign lns_hero = article.metafields.custom.image_une.value | default: article.image
  assign lns_show_hero = false
  if lns_hero != blank
    unless article.content contains '<img'
      assign lns_show_hero = true
    endunless
  endif
-%}
{%- if lns_show_hero -%}
  <figure class="article-hero">
    {{ lns_hero | image_url: width: 1600 | image_tag: loading: 'eager', fetchpriority: 'high', sizes: '(min-width: 990px) 900px, 100vw', widths: '600, 900, 1200, 1600', alt: article.image.alt | default: article.title, class: 'article-hero__img' }}
  </figure>
{%- endif -%}

<div class="article-content rte{% if section.settings.blog_capitalize_first %} capitalize-first-letter{% endif %}">
  {{ article.content }}
</div>

{%- if blog.comments_enabled? -%}
  {%- if number_of_comments > 0 -%}
    <hr class="hr--large">
    <h3>{{ 'blogs.comments.with_count' | t: count: number_of_comments }}</h3>
    <hr class="hr--small hr--clear">
  {%- endif -%}

  {%- paginate article.comments by 5 -%}
    <div id="comments">
      {%- if comment and comment.errors == blank -%}
        <hr class="hr--small hr--clear">
        <p class="note note--success">
          {%- if blog.moderated? -%}
            {{ 'blogs.comments.success_moderated' | t }}
          {%- else -%}
            {{ 'blogs.comments.success' | t }}
          {%- endif -%}
        </p>
      {%- endif -%}

      {%- if number_of_comments > 0 -%}
        <ul class="no-bullets">
          {%- if comment.status == 'pending' -%}
            <li id="Comment-{{ comment.id }}" class="article__comment">
              {%- render 'comment', comment: comment -%}
            </li>
          {%- endif -%}

          {%- for comment in article.comments -%}
            <li id="Comment-{{ comment.id }}" class="article__comment">
              {%- render 'comment', comment: comment -%}
            </li>

            {%- unless forloop.last -%}
              <li><hr class="hr--clear"></li>
            {%- endunless -%}
          {%- endfor -%}
        </ul>

        {%- if paginate.pages > 1 -%}
          {%- render 'pagination', paginate: paginate, hash: '#comments' -%}
        {%- endif -%}

      {%- endif -%}

      <hr class="hr--large">

      <header class="section-header">
        <h3 class="section-header__title">{{ 'blogs.comments.title' | t }}</h3>
      </header>

      <div class="form-vertical">
        {%- form 'new_comment', article -%}

          {{ form.errors | default_errors }}

          <div class="grid grid--small">
            <div class="grid__item medium-up--one-half">
              <label for="CommentAuthor">{{ 'blogs.comments.name' | t }}</label>
              <input class="input-full{% if form.errors contains 'author' %} error{% endif %}" type="text" name="comment[author]" id="CommentAuthor" value="{{ form.author }}" autocapitalize="words">
            </div>
            <div class="grid__item medium-up--one-half">
              <label for="CommentEmail">{{ 'blogs.comments.email' | t }}</label>
              <input class="input-full{% if form.errors contains 'email' %} error{% endif %}" type="email" name="comment[email]" id="CommentEmail" value="{{ form.email }}" autocorrect="off" autocapitalize="off">
            </div>
          </div>

          <label for="CommentBody">{{ 'blogs.comments.message' | t }}</label>
          <textarea class="input-full{% if form.errors contains 'body' %} error{% endif %}" name="comment[body]" id="CommentBody">{{ form.body }}</textarea>

          {%- if blog.moderated? -%}
            <p><small>{{ 'blogs.comments.moderated' | t }}</small></p>
          {%- endif -%}

          <button type="submit" class="btn btn--secondary">
            {{ 'blogs.comments.post' | t }}
          </button>

          {% comment %}
            Remove the following three lines of code to remove the note
            about being protected by Google's reCAPTCHA service.
            By removing it, the small reCAPTCHA widget will appear in the
            bottom right corner of the page.
          {% endcomment %}
          {{ 'shopify.online_store.spam_detection.disclaimer_html' | t }}

        {%- endform -%}
      </div>

    </div>
  {%- endpaginate -%}
{%- endif -%}

<hr class="hr--large">

{%- if section.settings.blog_show_tags and article.tags.size > 0 -%}
  <div class="article-tag__wrapper">
    <span class="label">{{ 'blogs.article.more_from' | t }}:</span>
    {%- for tag in article.tags -%}
      {% if tag contains "_" %}{%- assign tag_starts_with = tag | slice: 0 -%}{% if tag_starts_with == "_" %}{% if tag_count %}{%- assign tag_count = tag_count | minus: 1 | at_least: 0 -%}{% endif %}{% continue %}{% endif %}{% endif %}
      <a href="{{ blog.url }}/tagged/{{ tag | handle }}" class="article-tag">{{ tag }}</a>
    {%- endfor -%}
  </div>
{%- endif -%}

<div class="text-center">
  <a href="{{ blog.url }}" class="btn return-link"><svg aria-hidden="true" focusable="false" role="presentation" class="icon icon--wide icon-arrow-left" viewBox="0 0 50 15"><path d="M50 5.38v4.25H15V15L0 7.5 15 0v5.38z"/></svg> {{ 'blogs.article.back_to_blog' | t: title: blog.title }}</a>
</div>

{%- comment -%} Love'nSpa : JSON-LD Article + BreadcrumbList + FAQPage (metafield custom.faq) {%- endcomment -%}
{%- render 'lovenspa-article-jsonld', article: article, blog: blog -%}

{% style %}
  .article-page-header .article__sub-meta {
    margin-top: 0;
    margin-bottom: 1.35rem;
    font-size: calc(var(--typeBaseSize, 16px) * 0.875);
    opacity: 0.82;
  }
{% endstyle %}

{% schema %}
{
  "name": "t:sections.article-template.name",
  "class": "blog-layout__main",
  "settings": [
    {
      "type": "checkbox",
      "id": "blog_capitalize_first",
      "label": "t:sections.article-template.settings.blog_capitalize_first.label",
      "default": true
    },
    {
      "type": "checkbox",
      "id": "blog_show_tags",
      "label": "t:sections.article-template.settings.blog_show_tags.label",
      "default": true
    },
    {
      "type": "checkbox",
      "id": "blog_show_date",
      "label": "t:sections.article-template.settings.blog_show_date.label",
      "default": true
    },
    {
      "type": "checkbox",
      "id": "blog_show_comments",
      "label": "t:sections.article-template.settings.blog_show_comments.label",
      "default": true
    },
    {
      "type": "checkbox",
      "id": "blog_show_author",
      "label": "t:sections.article-template.settings.blog_show_author.label"
    }
  ]
}
{% endschema %}

sections/background-image-text.liquid:
{%- if section.settings.image != blank -%}
  {%- style -%}
    @media screen and (max-width: 768px) {
      .loaded.background-media-text--{{ section.id }} {
        background-image: url({{ section.settings.image | img_url: '350x350', crop: 'center' }});
        background-size: cover;
        background-position: 50% 50%;
      }
    }
  {%- endstyle -%}
{%- endif -%}

<div
  data-section-id="{{ section.id }}"
  data-section-type="background-image"
  class="background-media-text background-media-text--{{ section.id }} background-media-text--{{ section.settings.height }}"
  {% if section.settings.parallax %}data-parallax="true"{% endif %}>

  <div class="background-media-text__container">
    {%- if section.settings.parallax -%}
      <parallax-image class="parallax-container">
        <div class="parallax-image" data-movement="15%" data-parallax-image data-angle="{{ section.settings.parallax_direction }}">
    {%- endif -%}

      {%- if section.settings.image != blank -%}
        {% assign classes = 'image-fit background-media-text__image background-media-text__image--' | append: section.id %}

        {% render 'image-element'
          img: section.settings.image,
          img_width: 2400,
          classes: classes,
          alt: section.settings.image.alt,
          sizes: '100%'
        %}
      {%- else -%}
        {{ 'lifestyle-1' | placeholder_svg_tag: 'placeholder-svg' }}
      {%- endif -%}

    {%- if section.settings.parallax -%}
        </div>
      </parallax-image>
    {%- endif -%}
  </div>
  {%- if section.settings.subtitle != blank or section.settings.title != blank or section.settings.text != blank -%}
    <div class="background-media-text__inner">
      <div class="background-media-text__aligner background-media-text--{{ section.settings.layout }}">
        <div class="animation-contents">
          <div class="background-media-text__text">
            {%- if section.settings.subtitle != blank -%}
              <p class="accent-subtitle">{{ section.settings.subtitle }}</p>
            {%- endif -%}
            {%- if section.settings.title != blank -%}
              <p class="h3">{{ section.settings.title | escape }}</p>
            {%- endif -%}
            {%- if section.settings.text != blank -%}
              <div class="rte background-media-text__subtext">{{ section.settings.text }}</div>
            {%- endif -%}
            {%- if section.settings.button_label != blank and section.settings.button_link != blank -%}
              <a href="{{ section.settings.button_link }}" class="btn">
                {{ section.settings.button_label }}
              </a>
            {%- endif -%}
          </div>
        </div>
      </div>
    </div>
  {%- endif -%}
</div>

