sections/blog-header.liquid:
{%- comment -%} En-tête blog pleine largeur (au-dessus de la grille + sidebar). {%- endcomment -%}
<div class="blog-header" data-section-id="{{ section.id }}" data-section-type="blog-header">
  <div class="blog-header__inner">
    {%- if settings.show_breadcrumbs -%}
      <div class="blog-header__breadcrumbs">
        {%- render 'breadcrumbs' -%}
      </div>
    {%- endif -%}

    <header class="blog-header__head section-header{% if section.settings.show_tag_pills and blog.all_tags.size > 0 %} section-header--with-link{% endif %}">
      <div class="blog-header__title-row">
        <div class="blog-header__title-stack">
          <h1 class="blog-header__title section-header__title">
            {{ blog.title }}
            {%- if section.settings.blog_show_rss -%}
              <a href="{{ shop.url }}{{ blog.url }}.atom" class="rss-link blog-header__rss">
                <svg aria-hidden="true" focusable="false" role="presentation" class="icon icon-rss" viewBox="0 0 20 20">
                  <path fill="#444" d="M5.903 16.586a2.489 2.489 0 1 1-4.977 0 2.489 2.489 0 0 1 4.977 0zM12.956 19.075H9.43c0-4.688-3.817-8.505-8.505-8.505V7.044c6.638 0 12.031 5.393 12.031 12.031z"/><path fill="#444" d="M15.445 19.075c0-8.028-6.493-14.52-14.52-14.52V.925c10.019 0 18.15 8.131 18.15 18.15h-3.63z"/>
                </svg>
                <span class="icon__fallback-text">RSS</span>
              </a>
            {%- endif -%}
          </h1>
          {%- if section.settings.intro_chapo != blank -%}
            <div class="rte blog-header__chapo">{{ section.settings.intro_chapo }}</div>
          {%- endif -%}
        </div>
        {%- if section.settings.intro_kicker != blank -%}
          <p class="blog-header__kicker">{{ section.settings.intro_kicker | escape }}</p>
        {%- endif -%}
      </div>
    </header>

    {%- if section.settings.show_blog_search -%}
      <form
        action="{{ routes.search_url }}"
        method="get"
        class="input-group search-bar blog-header__search"
        role="search">
        <input type="hidden" name="type" value="article">
        <input type="hidden" name="options[prefix]" value="last">
        <input
          type="search"
          name="q"
          value=""
          placeholder="{{ 'blogs.general.search_placeholder' | t }}"
          class="input-group-field"
          aria-label="{{ 'blogs.general.search_articles_aria' | t }}">
        <label for="blog-header-search-submit-{{ section.id }}" class="hidden-label">{{ 'general.search.submit' | t }}</label>
        <div class="input-group-btn">
          <button type="submit" id="blog-header-search-submit-{{ section.id }}" class="btn btn--small btn--icon">
            <svg aria-hidden="true" focusable="false" role="presentation" class="icon icon-search" viewBox="0 0 64 64"><defs><style>.cls-1{fill:none;stroke:#000;stroke-miterlimit:10;stroke-width:2px}</style></defs><path class="cls-1" d="M47.16 28.58A18.58 18.58 0 1 1 28.58 10a18.58 18.58 0 0 1 18.58 18.58zM54 54L41.94 42"/></svg>
            <span class="icon__fallback-text">{{ 'general.search.submit' | t }}</span>
          </button>
        </div>
      </form>
    {%- endif -%}

    {%- liquid
      assign show_all_pill_active = true
      if current_tags != blank and current_tags.size > 0
        assign show_all_pill_active = false
      endif
    -%}
    {%- if section.settings.show_tag_pills and blog.all_tags.size > 0 -%}
      {%- liquid
        assign blog_header_valid_tag_count = 0
        for count_tag in blog.all_tags
          if count_tag contains '_'
            assign count_tag_first = count_tag | slice: 0
            if count_tag_first == '_'
              continue
            endif
          endif
          assign blog_header_valid_tag_count = blog_header_valid_tag_count | plus: 1
        endfor
      -%}
      <nav class="blog-header__tag-pills" aria-label="{{ 'blogs.general.tags_nav_aria' | t }}">
        <a
          href="{{ blog.url }}"
          class="blog-header__pill{% if show_all_pill_active %} is-active{% endif %}">
          {{ 'blogs.general.all_posts' | t }}
        </a>
        {%- assign blog_header_tag_idx = 0 -%}
        {%- for tag in blog.all_tags -%}
          {%- if tag contains '_' -%}
            {%- assign tag_starts_with = tag | slice: 0 -%}
            {%- if tag_starts_with == '_' -%}
              {%- continue -%}
            {%- endif -%}
          {%- endif -%}
          {%- assign blog_header_tag_idx = blog_header_tag_idx | plus: 1 -%}
          {%- if blog_header_tag_idx > 5 -%}
            {%- continue -%}
          {%- endif -%}
          {%- liquid
            assign pill_active = false
            if current_tags != blank and current_tags contains tag
              assign pill_active = true
            endif
          -%}
          <a
            href="{{ blog.url }}/tagged/{{ tag.handle }}"
            class="blog-header__pill{% if pill_active %} is-active{% endif %}">
            {{ tag }}
          </a>
        {%- endfor -%}

        {%- liquid
          assign blog_header_accordion_should_open = false
          if blog_header_valid_tag_count > 5 and current_tags != blank
            assign blog_header_idx_check = 0
            for tag_check in blog.all_tags
              if tag_check contains '_'
                assign chk_first = tag_check | slice: 0
                if chk_first == '_'
                  continue
                endif
              endif
              assign blog_header_idx_check = blog_header_idx_check | plus: 1
              if blog_header_idx_check > 5 and current_tags contains tag_check
                assign blog_header_accordion_should_open = true
              endif
            endfor
          endif
        -%}
        {%- if blog_header_valid_tag_count > 5 -%}
          <details
            class="blog-header__tag-accordion"
            id="blog-tag-accordion-{{ section.id }}"
            {% if blog_header_accordion_should_open %}
              open
            {% endif %}>
            <summary class="blog-header__tag-accordion-summary">
              <span class="blog-header__tag-accordion-label">{{ 'blogs.general.show_more_tags' | t }}</span>
            </summary>
            <div class="blog-header__tag-accordion-panel">
              {%- assign blog_header_tag_idx = 0 -%}
              {%- for tag in blog.all_tags -%}
                {%- if tag contains '_' -%}
                  {%- assign tag_starts_with = tag | slice: 0 -%}
                  {%- if tag_starts_with == '_' -%}
                    {%- continue -%}
                  {%- endif -%}
                {%- endif -%}
                {%- assign blog_header_tag_idx = blog_header_tag_idx | plus: 1 -%}
                {%- if blog_header_tag_idx <= 5 -%}
                  {%- continue -%}
                {%- endif -%}
                {%- liquid
                  assign pill_active = false
                  if current_tags != blank and current_tags contains tag
                    assign pill_active = true
                  endif
                -%}
                <a
                  href="{{ blog.url }}/tagged/{{ tag.handle }}"
                  class="blog-header__pill{% if pill_active %} is-active{% endif %}">
                  {{ tag }}
                </a>
              {%- endfor -%}
            </div>
          </details>
        {%- endif -%}
      </nav>
    {%- endif -%}
  </div>
</div>

{% style %}
  .blog-header {
    width: 100%;
    max-width: none;
    box-sizing: border-box;
  }
  .blog-header__inner {
    width: 100%;
    max-width: 100%;
  }
  .blog-header {
    --blog-header-gap: 20px;
    --blog-header-section: 20px;
    padding-bottom: 0;
    margin-bottom: 20px;
  }
  .blog-header__breadcrumbs {
    margin-bottom: 10px;
  }
  .blog-header__breadcrumbs .breadcrumb {
    font-size: calc(var(--typeBaseSize, 16px) * 0.75);
    opacity: 0.72;
    justify-content: flex-start;
    margin: 0;
  }
  .blog-header__head {
    text-align: left;
    margin-bottom: var(--blog-header-gap);
  }
  .blog-header__head.section-header {
    margin-bottom: var(--blog-header-gap);
  }
  .blog-header__title-row {
    display: flex;
    flex-wrap: wrap;
    align-items: flex-start;
    gap: 8px 16px;
    margin: 0 0 12px;
  }
  .blog-header__title-stack {
    flex: 1 1 auto;
    min-width: 0;
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    gap: 0;
  }
  @media only screen and (min-width: 768px) {
    .blog-header__title-stack {
      flex-direction: row;
      align-items: flex-start;
      gap: 20px;
    }
    .blog-header__title-stack > .blog-header__title {
      flex: 0 1 auto;
    }
    .blog-header__title-stack > .blog-header__chapo {
      margin-top: 0;
      flex: 1 1 0;
      min-width: 12rem;
      max-width: min(42rem, 58%);
    }
  }
  .blog-header__title {
    font-size: clamp(1.75rem, 4vw, 2.75rem);
    line-height: 1.15;
    margin: 0;
    letter-spacing: -0.02em;
  }
  .blog-header__rss {
    margin-left: 0.35rem;
    vertical-align: middle;
  }
  .blog-header__kicker {
    margin: 0;
    font-size: calc(var(--typeBaseSize, 16px) * 1.05);
    font-style: italic;
    color: var(--colorBtnPrimary, #c2185b);
    font-weight: 500;
    line-height: 1.4;
    flex: 0 1 auto;
    align-self: flex-start;
  }
  @media only screen and (min-width: 600px) {
    .blog-header__kicker {
      margin-left: auto;
      text-align: right;
      max-width: 28rem;
    }
  }
  .blog-header__chapo {
    margin: 10px 0 0;
    max-width: 42rem;
    width: 100%;
    text-align: left;
    font-size: calc(var(--typeBaseSize, 16px) * 0.9375);
    line-height: 1.55;
    opacity: 0.88;
  }
  @media only screen and (max-width: 767px) {
    .blog-header__chapo {
      max-width: 100%;
    }
  }
  .blog-header__chapo p:last-child {
    margin-bottom: 0;
  }
  .blog-header__search {
    width: 100%;
    max-width: 100%;
    margin: 0 0 20px;
    display: flex;
    align-items: stretch;
  }
  .blog-header__search .input-group-field {
    flex: 1 1 auto;
    min-width: 0;
    min-height: 0;
    padding: 0.45rem 0.85rem;
    font-size: 0.875rem;
    line-height: 1.35;
    border-radius: 8px 0 0 8px;
  }
  .blog-header__search .input-group-btn {
    flex-shrink: 0;
  }
  .blog-header__search .input-group-btn .btn {
    min-height: 0;
    padding: 0.45rem 0.65rem;
    height: 100%;
    border-radius: 0 8px 8px 0;
  }
  .blog-header__search .input-group-btn .icon {
    width: 1.1rem;
    height: 1.1rem;
  }
  .blog-header__tag-pills {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    justify-content: flex-start;
    margin: 0 0 20px;
    padding: 0;
  }
  .blog-header__pill {
    display: inline-block;
    padding: 0.4rem 0.95rem;
    border-radius: 999px;
    border: 1px solid rgba(0, 0, 0, 0.18);
    font-size: 0.65rem;
    line-height: 1.3;
    text-transform: uppercase;
    letter-spacing: 1px;
    text-decoration: none;
    color: inherit;
    transition: background 0.15s ease, border-color 0.15s ease;
  }
  .blog-header__pill:hover,
  .blog-header__pill:focus {
    border-color: rgba(0, 0, 0, 0.35);
    text-decoration: none;
  }
  .blog-header__pill.is-active {
    background: var(--colorBtnPrimary, #111);
    border-color: var(--colorBtnPrimary, #111);
    color: var(--colorBtnPrimaryText, #fff);
  }
  .blog-header__tag-accordion {
    flex: 1 1 100%;
    width: 100%;
    margin: 0;
    padding: 0;
    border: 0;
  }
  .blog-header__tag-accordion-summary {
    list-style: none;
    cursor: pointer;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    margin: 0;
    padding: 0.4rem 0.95rem;
    border-radius: 999px;
    border: 1px dashed rgba(0, 0, 0, 0.25);
    font-size: 0.65rem;
    line-height: 1.3;
    text-transform: uppercase;
    letter-spacing: 1px;
    color: inherit;
    background: rgba(0, 0, 0, 0.03);
    width: auto;
    max-width: 100%;
  }
  .blog-header__tag-accordion-summary::-webkit-details-marker {
    display: none;
  }
  .blog-header__tag-accordion-summary::after {
    content: '';
    display: inline-block;
    width: 0.35rem;
    height: 0.35rem;
    margin-left: 0.45rem;
    border-right: 1px solid currentColor;
    border-bottom: 1px solid currentColor;
    transform: rotate(45deg) translate(0, -0.1rem);
    opacity: 0.65;
    transition: transform 0.2s ease;
  }
  .blog-header__tag-accordion[open] .blog-header__tag-accordion-summary::after {
    transform: rotate(-135deg) translate(0, 0.05rem);
  }
  .blog-header__tag-accordion-panel {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    margin-top: 8px;
    padding-top: 4px;
  }
  @media only screen and (min-width: 768px) {
    .blog-header__tag-accordion {
      display: contents;
    }
    .blog-header__tag-accordion-summary {
      display: none !important;
    }
    .blog-header__tag-accordion-panel {
      display: contents;
    }
    .blog-header__tag-accordion-panel .blog-header__pill {
      margin-top: 0;
    }
  }
{% endstyle %}

{% schema %}
