sections/blog-posts.liquid:
{%- liquid
  assign blog = blogs[section.settings.blog]
  assign sidebar_count = 8

  assign have_blog = true
  if blog.empty? or blog.articles.size == 0
    assign have_blog = false
  endif

  # Love'nSpa : n'afficher que les articles de la rédaction (TOFU + Destinations),
  # dans l'ordre du métafield de blog custom.articles_classiques (jamais le fil automatique).
  assign bp_list = blog.metafields.custom.articles_classiques.value
  assign bp_use_list = false
  if bp_list != blank and bp_list.size > 0
    assign bp_use_list = true
  endif
  assign bp_prefix = blog.handle | append: '/'
-%}

{%- if section.settings.divider -%}<div class="section--divider">{%- endif -%}

<div class="index-section blog-posts-section color-scheme-{{ section.settings.color_scheme | default: 'none' }}">
  {%- if section.settings.color_scheme != 'none' and section.settings.color_scheme != blank -%}
    {%- render 'color-scheme-texture', color_scheme: section.settings.color_scheme -%}
  {%- endif -%}

  <div class="page-width">

  {%- if section.settings.title != blank -%}
    <header class="section-header section-header--with-link">
      <h2 class="section-header__title">
        {{ section.settings.title | escape }}
      </h2>
      <a href="{{ blog.url }}" class="section-header__link">{{ 'blogs.article.view_all' | t }}</a>
    </header>
  {%- endif -%}

  <div class="blog-layout blog-layout--homepage-posts">

    <div class="blog-layout__main">
      <div class="new-grid">
        {%- if have_blog and bp_use_list -%}
          {%- assign bp_n = 0 -%}
          {%- for h in bp_list -%}
            {%- assign bp_key = bp_prefix | append: h -%}
            {%- assign article = articles[bp_key] -%}
            {%- if article == blank -%}{%- continue -%}{%- endif -%}
            {%- render 'article-grid-item',
              blog: blog,
              article: article,
              style: 'large',
              show_tags: section.settings.blog_show_tags,
              show_date: section.settings.blog_show_date,
              show_comments: section.settings.blog_show_comments,
              show_author: section.settings.blog_show_author,
              image_size: section.settings.blog_image_size -%}
            {%- break -%}
          {%- endfor -%}
        {%- elsif have_blog -%}
          {%- for article in blog.articles limit: 1 -%}
            {%- render 'article-grid-item',
              blog: blog,
              article: article,
              style: 'large',
              show_tags: section.settings.blog_show_tags,
              show_date: section.settings.blog_show_date,
              show_comments: section.settings.blog_show_comments,
              show_author: section.settings.blog_show_author,
              image_size: section.settings.blog_image_size -%}
          {%- endfor -%}
        {%- else -%}
          {%- render 'article-grid-item',
            blog: false,
            article: false,
            style: 'large',
            show_tags: section.settings.blog_show_tags,
            show_date: section.settings.blog_show_date,
            show_comments: section.settings.blog_show_comments,
            show_author: section.settings.blog_show_author,
            image_size: 'landscape' -%}
        {%- endif -%}
      </div>
    </div>
    <div class="blog-layout__sidebar">
      <div class="h4">{{ 'blogs.article.latest_posts' | t }}</div>

      <div class="blog-posts__carousel-outer page-width--flush-small">
        <div class="blog-posts__articles-grid new-grid product-grid scrollable-grid--small">
          {%- if have_blog and bp_use_list -%}
            {%- assign bp_seen = 0 -%}
            {%- assign bp_shown = 0 -%}
            {%- for h in bp_list -%}
              {%- if bp_shown >= sidebar_count -%}{%- break -%}{%- endif -%}
              {%- assign bp_key = bp_prefix | append: h -%}
              {%- assign article = articles[bp_key] -%}
              {%- if article == blank -%}{%- continue -%}{%- endif -%}
              {%- assign bp_seen = bp_seen | plus: 1 -%}
              {%- if bp_seen == 1 -%}{%- continue -%}{%- endif -%}
              {%- assign bp_shown = bp_shown | plus: 1 -%}
              {%- render 'article-grid-item',
                blog: blog,
                article: article,
                style: 'compact',
                show_tags: section.settings.blog_show_tags,
                show_date: section.settings.blog_show_date,
                show_comments: section.settings.blog_show_comments,
                show_author: section.settings.blog_show_author,
                image_size: section.settings.blog_image_size -%}
            {%- endfor -%}
          {%- elsif have_blog -%}
            {%- for article in blog.articles limit: sidebar_count offset: 1 -%}
              {%- render 'article-grid-item',
                blog: blog,
                article: article,
                style: 'compact',
                show_tags: section.settings.blog_show_tags,
                show_date: section.settings.blog_show_date,
                show_comments: section.settings.blog_show_comments,
                show_author: section.settings.blog_show_author,
                image_size: section.settings.blog_image_size -%}
            {%- endfor -%}
          {%- else -%}
            {%- for i in (1..sidebar_count) -%}
              {%- render 'article-grid-item',
                blog: false,
                article: false,
                style: 'compact',
                show_tags: section.settings.blog_show_tags,
                show_date: section.settings.blog_show_date,
