    .blog-layout__sidebar { display: none; }
  </style>
{%- endif -%}

{% style %}
  {% render 'article-blog-card-horizontal-styles' %}
  .blog-sidebar__block-heading {
    margin: 0 0 0.85rem;
    font-size: clamp(1rem, 2.2vw, 1.25rem);
    font-weight: 700;
    line-height: 1.2;
    letter-spacing: -0.02em;
  }
  .blog-layout__sidebar .theme-block--article:not(:last-child) {
    margin-bottom: 12px;
  }
  .blog-layout__sidebar .theme-block--sidebar-product:not(:last-child) {
    margin-bottom: 12px;
  }
{% endstyle %}

{%- for block in section.blocks -%}
  {%- case block.type -%}
    {%- when 'article' -%}
      {%- assign article_object = articles[block.settings.article] -%}
      <div class="theme-block theme-block--article" {{ block.shopify_attributes }}>
        {%- if block.settings.title != blank -%}
          <h3 class="blog-sidebar__block-heading">{{ block.settings.title | escape }}</h3>
        {%- endif -%}
        {%- unless article_object.empty? -%}
          {%- render 'article-blog-card-horizontal',
            article: article_object,
            blog: blog,
            show_tags: block.settings.blog_show_tags,
            show_date: block.settings.blog_show_date,
            show_author: block.settings.blog_show_author
          -%}
        {%- endunless -%}
      </div>
    {%- when 'tags' -%}
      {%- if blog.all_tags.size > 0 -%}
        <div class="theme-block" {{ block.shopify_attributes }}>
          <h4>{{ 'blogs.article.explore_more' | t }}</h4>
          <ul class="no-bullets tag-list">
            {%- for tag in blog.all_tags -%}
              {% if tag contains "_" %}{%- assign tag_starts_with = tag | slice: 0 -%}{% if tag_starts_with == "_" %}{% if tag_count %}{%- assign tag_count = tag_count | minus: 1 | at_least: 0 -%}{% endif %}{% continue %}{% endif %}{% endif %}
              <li class="tag tag--inline">
                <a href="{{ blog.url }}/tagged/{{ tag.handle }}" class="article-tag">{{ tag }}</a>
              </li>
            {%- endfor -%}
          </ul>
        </div>
      {%- endif -%}
    {%- when 'product' -%}
      {%- assign product = all_products[block.settings.featured_product] -%}
      {%- unless product.empty? -%}
        <div class="theme-block theme-block--sidebar-product" {{ block.shopify_attributes }}>
          <h3 class="visually-hidden">{{ 'blogs.article.featured_product' | t }}</h3>
          {%- render 'blog-sidebar-featured-product', product: product -%}
        </div>
      {%- endunless -%}
    {%- when 'liquid' -%}
      {{ block.settings.liquid }}
    {%- when 'share' -%}
      {%- if article -%}
        <div class="theme-block" {{ block.shopify_attributes }}>
          <h4>{{ 'general.social.share_this' | t }}</h4>
          {%- render 'social-sharing',
            share_title: article.title,
            share_permalink: article.url,
            share_image: article.image -%}
        </div>
      {%- endif -%}
  {%- endcase -%}
{%- endfor -%}

