sections/blog-template.liquid:
{%- paginate blog.articles by 10 -%}
  {%- liquid
    assign featured_layout = false
    if section.settings.enable_featured_layout and paginate.current_page == 1
      if current_tags == blank or current_tags.size == 0
        assign featured_layout = true
      endif
    endif
  -%}
  <div class="blog-template blog-template--mockup" data-section-id="{{ section.id }}" data-section-type="blog">
    {%- if featured_layout and blog.articles.size > 0 -%}
      <div class="blog-template__hero-wrap">
        {%- assign feat_article = blog.articles | first -%}
        {%- render 'article-featured-hero',
          article: feat_article,
          show_tags: section.settings.blog_show_tags,
          show_date: section.settings.blog_show_date
        -%}
      </div>
    {%- endif -%}

    {%- liquid
      assign show_card_grid = false
      if featured_layout and blog.articles.size > 1
        assign show_card_grid = true
      elsif featured_layout == false and blog.articles.size > 0
        assign show_card_grid = true
      endif
    -%}

    {%- if show_card_grid -%}
      <div class="blog-template__grid-head" id="blog-articles-list">
        <h2 class="blog-template__grid-title">
          {{ section.settings.grid_heading_before | escape }}
          <em class="blog-template__grid-title-accent">{{ section.settings.grid_heading_emphasis | escape }}</em>
        </h2>
        <a href="{{ blog.url }}#blog-articles-list" class="blog-template__grid-all text-link">{{ 'blogs.general.view_all' | t }}</a>
      </div>

      <div class="blog-template__article-grid">
        {%- if featured_layout and blog.articles.size > 1 -%}
          {%- for article in blog.articles offset: 1 limit: 9 -%}
            {%- render 'article-blog-card',
              article: article,
              blog: blog,
              show_tags: section.settings.blog_show_tags,
              show_date: section.settings.blog_show_date,
              show_author: section.settings.blog_show_author
            -%}
          {%- endfor -%}
        {%- else -%}
          {%- for article in blog.articles -%}
            {%- render 'article-blog-card',
              article: article,
              blog: blog,
              show_tags: section.settings.blog_show_tags,
              show_date: section.settings.blog_show_date,
              show_author: section.settings.blog_show_author
            -%}
          {%- endfor -%}
        {%- endif -%}
      </div>
    {%- endif -%}

    {%- liquid
      if paginate.pages > 1
        render 'pagination', paginate: paginate
      endif
    -%}
  </div>
{%- endpaginate -%}

{% style %}
  .blog-template--mockup {
    --blog-mockup-gap: clamp(1rem, 3vw, 2rem);
    --blog-mockup-section: clamp(2rem, 5vw, 3.5rem);
  }
  .blog-template__hero-wrap {
    width: 100%;
    max-width: 100%;
    margin-bottom: var(--blog-mockup-section);
  }
  .blog-hero__link {
    display: block;
    text-decoration: none;
    color: inherit;
    border-radius: 8px;
    overflow: hidden;
  }
  .blog-hero__media {
    position: relative;
    min-height: clamp(260px, 40vw, 520px);
    background: rgba(0, 0, 0, 0.06);
  }
  .blog-hero__img,
  .blog-hero__placeholder {
    width: 100%;
    height: 100%;
    min-height: clamp(260px, 40vw, 520px);
    object-fit: cover;
    display: block;
  }
  .blog-hero__placeholder {
    background: linear-gradient(135deg, rgba(0, 0, 0, 0.08), rgba(0, 0, 0, 0.02));
  }
  .blog-hero__scrim {
    position: absolute;
    inset: 0;
    background: linear-gradient(to top, rgba(0, 0, 0, 0.78) 0%, rgba(0, 0, 0, 0.25) 45%, transparent 72%);
    pointer-events: none;
  }
  .blog-hero__overlay {
    position: absolute;
    left: 0;
    right: 0;
    bottom: 0;
    padding: clamp(1rem, 3vw, 1.75rem);
    color: #fff;
    text-align: left;
  }
  .blog-hero__badge {
    display: inline-block;
    margin-bottom: 0.5rem;
    padding: 0.35rem 0.75rem;
    border-radius: 999px;
    font-size: 0.65rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    background: var(--colorBtnPrimary, #c2185b);
    color: var(--colorBtnPrimaryText, #fff);
  }
  .blog-hero__title {
    margin: 0 0 0.4rem;
    font-size: clamp(1.35rem, 3.2vw, 2.15rem);
    line-height: 1.2;
    font-weight: 700;
    color: #fff;
  }
  .blog-hero__meta {
    font-size: 0.75rem;
    opacity: 0.85;
    margin-bottom: 0.5rem;
  }
  .blog-hero__meta-sep {
    margin: 0 0.35rem;
  }
  .blog-hero__excerpt {
    margin: 0 0 0.65rem;
    font-size: 0.875rem;
    line-height: 1.45;
    opacity: 0.92;
    display: -webkit-box;
    -webkit-line-clamp: 3;
    -webkit-box-orient: vertical;
    overflow: hidden;
  }
  .blog-hero__cta {
    font-size: 0.8rem;
    font-weight: 600;
    text-decoration: underline;
    text-underline-offset: 3px;
  }
  .blog-template__grid-head {
    display: flex;
    flex-wrap: wrap;
    align-items: baseline;
    justify-content: space-between;
    gap: 0.75rem;
    margin-bottom: 1.25rem;
    padding-top: 0.5rem;
  }
  .blog-template__grid-title {
    margin: 0;
    font-size: clamp(1.15rem, 2.5vw, 1.5rem);
    font-weight: 700;
    line-height: 1.2;
  }
  .blog-template__grid-title-accent {
    font-style: italic;
    font-weight: 600;
    color: var(--colorBtnPrimary, #c2185b);
  }
  .blog-template__grid-all {
    font-size: 0.8rem;
    font-weight: 600;
    white-space: nowrap;
  }
  .blog-template__article-grid {
    display: grid;
    grid-template-columns: 1fr;
    gap: clamp(1.5rem, 3vw, 2.25rem);
    margin-bottom: var(--blog-mockup-section);
  }
  @media only screen and (min-width: 700px) {
    .blog-template__article-grid {
      grid-template-columns: repeat(2, minmax(0, 1fr));
    }
  }
  @media only screen and (min-width: 990px) {
    .blog-template__article-grid {
      grid-template-columns: repeat(3, minmax(0, 1fr));
    }
  }
  {% render 'article-blog-card-styles' %}
  .blog-template--mockup .pagination {
    margin-top: 0.5rem;
    margin-bottom: 2rem;
    justify-content: center;
  }
{% endstyle %}

