sections/collection-header.liquid:
{%- liquid
  assign loven_hide_collection_extra = false
  if request.page_type == 'collection' and current_page > 1
    assign loven_hide_collection_extra = true
  endif
-%}
{%- unless loven_hide_collection_extra -%}
{%- assign disable_sticky_header = false -%}

{%- if section.settings.enable -%}
  {% style %}
    @media only screen and (max-width: 768px) {
      .template-collection h1.section-header__title {
        font-size: 18px;
      }
      .template-collection [data-collection-count] {
        display: none !important;
      }
    }
  {% endstyle %}
  {%- if section.settings.collection_image_enable and collection.image -%}
    {% style %}
      @media screen and (min-width: 769px) {
        .collection-content {
          border: 0;
          margin-top: 0;
        }
      }
    {% endstyle %}
    <div
      id="CollectionHeaderSection"
      data-section-id="{{ section.id }}"
      data-section-type="collection-header"
      {% if section.settings.parallax %}
        data-parallax="true"
      {% endif %}
    >
      {%- assign img_url = collection.image | img_url: '1x1' | replace: '_1x1.', '_{width}x.' -%}

      <div class="collection-hero loading">
        {%- if section.settings.parallax -%}
          <parallax-image class="parallax-container">
            <div
              class="parallax-image"
              data-movement="15%"
              data-parallax-image
              data-angle="{{ section.settings.parallax_direction }}"
            >
        {%- endif -%}

        {% render 'image-element',
          img: collection.image,
          img_width: 2400,
          classes: 'collection-hero__image image-fit',
          alt: collection.image.alt,
          preload: true,
          sizes: '100%',
          loading: 'eager'
        %}

        {%- if section.settings.parallax -%}
          </div>
          </parallax-image>
        {%- endif -%}

        <div class="collection-hero__content">
          <div class="page-width">
            <header class="section-header section-header--flush">
              {% if template.name == 'collection' %}
                <h1 class="section-header__title">
                  {% if collection.metafields.accentuate.type_de_collection == 'région' %}
                    Love Rooms en {{ collection.title }} : hébergements avec jacuzzi privatif et spa
                  {% elsif collection.metafields.accentuate.type_de_collection == 'ville' %}
                    Love rooms à {{ collection.title }} : hébergements avec jacuzzi privatif et spa
                  {% endif %}
                </h1>
              {% endif %}
            </header>
          </div>
        </div>
      </div>
    </div>

    <div class="page-width medium-up--hide" data-collection-count style="padding-top: 15px;">
      {{ 'collections.general.items_with_count' | t: count: collection.products_count }}
    </div>

  {%- else -%}
    {%- assign disable_sticky_header = true -%}
    <div class="page-full page-content page-content--top">
      <header class="section-header section-header--flush">
        <h1 class="section-header__title">
          {% if collection.metafields.accentuate.type_de_collection == 'région' %}
            Love Rooms en {{ collection.title }}
          {% elsif collection.metafields.accentuate.type_de_collection == 'ville' %}
            Love rooms à {{ collection.title }}
          {% elsif collection.metafields.accentuate.type_de_collection == 'département' %}
            Love Rooms en {{ collection.title }}
          {% else %}
            {{ collection.title }}
          {% endif %}
        </h1>
        <p class="medium-up--hide" data-collection-count>
          {{ 'collections.general.items_with_count' | t: count: collection.products_count }}
        </p>
      </header>
    </div>
  {%- endif -%}
{% else %}
  {%- assign disable_sticky_header = true -%}
{%- endif -%}

