sections/compositions-idees.liquid:
{%- comment -%}
  Cabania — Compositions : galerie d'idées (inspiration, sans achat).
  Chaque bloc choisit une idée ; photo, plan, recette et cotes viennent de snippets/compositions-idee.liquid (généré).
  Titre, texte et produit associé du bloc remplacent ceux par défaut s'ils sont renseignés.
{%- endcomment -%}
{{ 'compositions.css' | asset_url | stylesheet_tag }}
<script src="{{ 'compositions.js' | asset_url }}" defer="defer"></script>

<div class="cab">
  <div class="cab-section cab-section--blanc cab-galerie">
    <div class="page-width">
      {%- if section.settings.title != blank or section.settings.text != blank -%}
        <div class="cab-head" style="margin-bottom: 36px;">
          {%- if section.settings.title != blank -%}<h2 class="cab-h2">{{ section.settings.title | escape }}</h2>{%- endif -%}
          {%- if section.settings.text != blank -%}<div class="cab-lead cab-rte">{{ section.settings.text }}</div>{%- endif -%}
        </div>
      {%- endif -%}
      {%- render 'compositions-data', jeu: 'idees' -%}
      <div class="cab-cards">
        {%- for block in section.blocks -%}
          <div class="cab-card-wrap" {{ block.shopify_attributes }}>
            {%- render 'compositions-idee', idee: block.settings.idee, titre: block.settings.title, texte: block.settings.text, produit: block.settings.product, id: block.id -%}
          </div>
        {%- endfor -%}
      </div>
    </div>
  </div>
</div>

