sections/destination-links-tabs.liquid:
{%- liquid
  assign tabs_pairs_csv = 'regions::Régions||departements::Départements||villes::Villes||destinations::Destinations||equipements::Équipements||'
  assign tabs_pairs = tabs_pairs_csv | split: '||'
-%}

{%- comment -%}
  Sans {% paginate %}, Shopify limite fortement metaobjects.*.values en Liquid.
  On garde paginate by 250 **sans liens de pagination** : une seule page HTML, jusqu’à 250 métaobjets
  pour pouvoir tirer au hasard jusqu’à 50 liens par onglet.
{%- endcomment -%}
{% paginate shop.metaobjects.destination_link.values by 250 %}
  {%- liquid
    assign items = shop.metaobjects.destination_link.values
    if items == blank
      assign items = metaobjects.destination_link.values
    endif
    if items != blank
      assign items_shuffled = items | shuffle
    else
      assign items_shuffled = items
    endif
  -%}

{% if items != blank %}
  <div
    class="page-full destination-links destination-links--{{ section.id }}"
    data-section-id="{{ section.id }}"
    data-collapsed-rows="3"
    data-mobile-collapsed-items="6">
    <div class="page-width">
      <h2 class="destination-links__heading">{{ section.settings.heading }}</h2>

      <div class="destination-links__tabs" role="tablist" aria-label="Onglets destinations">
        {%- assign first_tab_rendered = false -%}
        {%- for tab_pair in tabs_pairs -%}
          {%- if tab_pair != blank -%}
            {%- assign tab_parts = tab_pair | split: '::' -%}
            {%- assign tab_key = tab_parts[0] -%}
            {%- assign tab_name = tab_parts[1] -%}
            <button
              type="button"
              class="destination-links__tab{% unless first_tab_rendered %} is-active{% endunless %}"
              data-tab-trigger="{{ tab_key }}"
              role="tab"
              aria-selected="{% unless first_tab_rendered %}true{% else %}false{% endunless %}">
              {{ tab_name }}
            </button>
            {%- assign first_tab_rendered = true -%}
          {%- endif -%}
        {%- endfor -%}
      </div>

      {%- if section.settings.show_debug -%}
        <div
          class="destination-links__debug"
          style="margin-top:12px;padding:12px;background:#f4f4f4;border:1px dashed #999;font-family:monospace;font-size:11px;line-height:1.4;overflow:auto;max-height:320px;">
          <div style="font-weight:700;margin-bottom:8px;">DEBUG — métaobjets `destination_link`</div>
          <div style="margin-bottom:8px;color:#333;">
            Source Liquid (batch max {{ paginate.page_size }}) :
            <strong>{{ items.size }}</strong> métaobjets sur <strong>{{ paginate.items }}</strong> au total.
            Affichage : max 50 liens par onglet après mélange aléatoire.
          </div>
          <table style="width:100%;border-collapse:collapse;">
            <thead>
              <tr style="text-align:left;border-bottom:1px solid #ccc;">
                <th style="padding:4px;">#</th>
                <th style="padding:4px;">handle</th>
                <th style="padding:4px;">tab (brut)</th>
                <th style="padding:4px;">tab mappé</th>
                <th style="padding:4px;">title</th>
                <th style="padding:4px;">url</th>
              </tr>
            </thead>
            <tbody>
              {%- for item in items -%}
                {%- liquid
                  assign dbg_tab_raw = item.tab.value | default: item.tab | append: '' | strip
                  assign item_tab = dbg_tab_raw | downcase
                  assign item_tab = item_tab | replace: ' ', ' '
                  assign item_tab = item_tab | replace: 'é', 'e'
                  assign item_tab = item_tab | replace: 'è', 'e'
                  assign item_tab = item_tab | replace: 'ê', 'e'
                  assign item_tab = item_tab | replace: 'ë', 'e'
                  assign item_tab = item_tab | replace: 'à', 'a'
                  assign item_tab = item_tab | replace: 'â', 'a'
                  assign item_tab = item_tab | replace: 'î', 'i'
                  assign item_tab = item_tab | replace: 'ï', 'i'
                  assign item_tab = item_tab | replace: 'ô', 'o'
                  assign item_tab = item_tab | replace: 'ö', 'o'
                  assign item_tab = item_tab | replace: 'ù', 'u'
                  assign item_tab = item_tab | replace: 'û', 'u'
                  assign item_tab = item_tab | replace: 'ü', 'u'
                  assign dbg_key = ''
                  if item_tab == 'regions'
                    assign dbg_key = 'regions'
                  elsif item_tab == 'departements'
                    assign dbg_key = 'departements'
                  elsif item_tab == 'villes'
                    assign dbg_key = 'villes'
                  elsif item_tab == 'destinations'
                    assign dbg_key = 'destinations'
                  elsif item_tab == 'equipements'
                    assign dbg_key = 'equipements'
                  endif
                  assign dbg_title = item.title.value | default: item.title | default: item.titre.value | default: item.nom.value
                  assign dbg_coll = item.collections.value | default: item.collection.value | default: item.collections | default: item.collection
                  assign dbg_url = ''
                  if dbg_coll != blank
                    if dbg_coll.url
                      assign dbg_url = dbg_coll.url
                    elsif dbg_coll.first and dbg_coll.first.url
                      assign dbg_url = dbg_coll.first.url
                    endif
                  endif
                  assign dbg_link = item.link.value | default: item.link
                  if dbg_url == blank and dbg_link != blank
                    if dbg_link.url
                      assign dbg_url = dbg_link.url
                    else
                      assign dbg_url = dbg_link | append: ''
                    endif
                  endif
                -%}
                <tr style="border-bottom:1px solid #e0e0e0;vertical-align:top;">
                  <td style="padding:4px;">{{ forloop.index }}</td>
                  <td style="padding:4px;word-break:break-all;">{{ item.handle }}</td>
                  <td style="padding:4px;word-break:break-all;">{{ dbg_tab_raw | escape }}</td>
                  <td style="padding:4px;">{% if dbg_key != blank %}{{ dbg_key }}{% else %}<span style="color:#c00;">(aucun)</span>{% endif %}</td>
                  <td style="padding:4px;word-break:break-word;">{{ dbg_title | escape }}</td>
                  <td style="padding:4px;word-break:break-all;">{{ dbg_url | escape }}</td>
                </tr>
              {%- endfor -%}
            </tbody>
          </table>
        </div>
      {%- endif -%}

      <div class="destination-links__body is-collapsed" data-destination-body>
        {%- assign first_panel_rendered = false -%}
        {%- for tab_pair in tabs_pairs -%}
          {%- if tab_pair != blank -%}
            {%- assign tab_parts = tab_pair | split: '::' -%}
            {%- assign tab_key = tab_parts[0] -%}
            {%- assign tab_name = tab_parts[1] -%}
            <div
              class="destination-links__panel{% unless first_panel_rendered %} is-active{% endunless %}"
              data-tab-panel="{{ tab_key }}"
              role="tabpanel">
              <div class="destination-links__grid">
              {%- liquid
                assign tab_shown = 0
              -%}
              {%- for item in items_shuffled -%}
                {%- liquid
                  assign tab_field = item.tab.value | default: item.tab
                  assign item_tab = tab_field | append: '' | strip | downcase
                  assign item_tab = item_tab | replace: ' ', ' '
                  assign item_tab = item_tab | replace: 'é', 'e'
                  assign item_tab = item_tab | replace: 'è', 'e'
                  assign item_tab = item_tab | replace: 'ê', 'e'
                  assign item_tab = item_tab | replace: 'ë', 'e'
                  assign item_tab = item_tab | replace: 'à', 'a'
                  assign item_tab = item_tab | replace: 'â', 'a'
                  assign item_tab = item_tab | replace: 'î', 'i'
                  assign item_tab = item_tab | replace: 'ï', 'i'
                  assign item_tab = item_tab | replace: 'ô', 'o'
                  assign item_tab = item_tab | replace: 'ö', 'o'
                  assign item_tab = item_tab | replace: 'ù', 'u'
                  assign item_tab = item_tab | replace: 'û', 'u'
                  assign item_tab = item_tab | replace: 'ü', 'u'
                  assign item_tab_key = ''
                  if item_tab == 'regions'
                    assign item_tab_key = 'regions'
                  elsif item_tab == 'departements'
                    assign item_tab_key = 'departements'
                  elsif item_tab == 'villes'
                    assign item_tab_key = 'villes'
                  elsif item_tab == 'destinations'
                    assign item_tab_key = 'destinations'
                  elsif item_tab == 'equipements'
                    assign item_tab_key = 'equipements'
                  endif
                  assign item_title = item.title.value | default: item.title | default: item.titre.value | default: item.nom.value
                  assign item_subtitle = item.subtitle.value | default: item.subtitle | default: item.sous_titre.value | default: item.description.value
                  assign linked_collection = item.collections.value | default: item.collection.value | default: item.collections | default: item.collection
                  assign item_link = item.link.value | default: item.link

                  assign item_url = ''
                  if linked_collection != blank
                    if linked_collection.url
                      assign item_url = linked_collection.url
                    elsif linked_collection.first and linked_collection.first.url
                      assign item_url = linked_collection.first.url
                    endif
                  elsif item_link != blank
                    if item_link.url
                      assign item_url = item_link.url
                    else
                      assign item_url = item_link
                    endif
                  endif
                  if item_title == blank and linked_collection != blank and linked_collection.title != blank
                    assign item_title = linked_collection.title
                  endif
                -%}

                {%- if item_tab_key == tab_key and item_title != blank and tab_shown < 50 -%}
                  {%- liquid
                    assign tab_shown = tab_shown | plus: 1
                  -%}
                  {%- if item_url != blank -%}
                    <a class="destination-links__item" href="{{ item_url }}">
                      <span class="destination-links__title">{{ item_title }}</span>
                      {%- if item_subtitle != blank -%}
                        <span class="destination-links__subtitle">{{ item_subtitle }}</span>
                      {%- endif -%}
                    </a>
                  {%- else -%}
                    <div class="destination-links__item">
                      <span class="destination-links__title">{{ item_title }}</span>
                      {%- if item_subtitle != blank -%}
                        <span class="destination-links__subtitle">{{ item_subtitle }}</span>
                      {%- endif -%}
                    </div>
                  {%- endif -%}
                {%- endif -%}
              {%- endfor -%}
              </div>
            </div>
            {%- assign first_panel_rendered = true -%}
          {%- endif -%}
        {%- endfor -%}
      </div>
      <button type="button" class="destination-links__toggle" data-destination-toggle>Afficher plus</button>
    </div>
  </div>

  {% style %}
    .destination-links {
      padding: 24px 0;
      border-top: 1px solid var(--colorBorder);
    }

    .destination-links__heading {
      margin: 0 0 14px;
      font-size: 28px;
      line-height: 1.2;
    }

    .destination-links__tabs {
      display: flex;
      gap: 14px;
      overflow-x: auto;
      border-bottom: 1px solid var(--colorBorder);
      margin-bottom: 16px;
      padding-bottom: 8px;
    }

    .destination-links__tab {
      border: 0;
      background: transparent;
      padding: 0 0 8px;
      font-size: 13px;
      color: #6b6b6b;
      cursor: pointer;
      border-bottom: 2px solid transparent;
      white-space: nowrap;
    }

    .destination-links__tab.is-active {
      color: #222;
      border-bottom-color: #222;
      font-weight: 600;
    }

    .destination-links__panel {
      display: none;
    }

    .destination-links__panel.is-active {
      display: block;
    }

    .destination-links__body {
      position: relative;
    }

    .destination-links__toggle {
      margin-top: 10px;
      border: 1px solid var(--colorBorder);
      background: #fff;
      border-radius: 999px;
      padding: 8px 14px;
      font-size: 13px;
      cursor: pointer;
    }

    .destination-links__grid {
      display: grid;
      grid-template-columns: repeat(6, minmax(0, 1fr));
      gap: 10px 18px;
    }

    .destination-links__item {
      display: block;
      text-decoration: none;
      color: inherit;
      padding: 4px 0;
    }

    /* `display: block` cassait le masquage par [hidden] sur les <a> */
    .destination-links__item[hidden],
    .destination-links__item.destination-links__item--clamped {
      display: none !important;
    }

    .destination-links__title {
      display: block;
      font-size: 13px;
      line-height: 1.25;
      font-weight: 600;
      margin-bottom: 2px;
    }

    .destination-links__subtitle {
      display: block;
      font-size: 12px;
      line-height: 1.2;
      color: #6b6b6b;
    }

    @media screen and (max-width: 1200px) {
      .destination-links__grid {
        grid-template-columns: repeat(4, minmax(0, 1fr));
      }
    }

    @media screen and (max-width: 768px) {
      .destination-links__heading {
        font-size: 22px;
      }

      .destination-links__grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
      }
    }
  {% endstyle %}

  <script>
    (() => {
      const root = document.querySelector('.destination-links--{{ section.id }}');
      if (!root) return;

      const tabs = root.querySelectorAll('[data-tab-trigger]');
      const panels = root.querySelectorAll('[data-tab-panel]');
      const body = root.querySelector('[data-destination-body]');
      const toggleBtn = root.querySelector('[data-destination-toggle]');

      const collapsedRows = Math.max(1, parseInt(root.getAttribute('data-collapsed-rows'), 10) || 3);
      const mobileCollapsedItems = Math.max(
        1,
        parseInt(root.getAttribute('data-mobile-collapsed-items'), 10) || 6
      );
      /** Même logique que les @media de la grille (768 / 1200 px), via innerWidth (plus fiable que matchMedia seul). */
      const getGridColumnCount = () => {
        /* Nombre réel de colonnes de la grille active : suit aussi les feuilles qui
           redéfinissent la grille (ex. lns-home.css sur l'accueil). */
        const activeGrid = root.querySelector('.destination-links__panel.is-active .destination-links__grid');
        if (activeGrid) {
          const cols = getComputedStyle(activeGrid).gridTemplateColumns.split(' ').filter(Boolean).length;
          if (cols > 0) return cols;
        }
        const w = window.innerWidth;
        if (w <= 768) return 2;
        if (w <= 1200) return 4;
        return 6;
      };

      const isMobileLayout = () => window.innerWidth <= 768;

      /** Mobile : 6 items (3 lignes × 2 col). Sinon : collapsedRows × colonnes. */
      const getCollapsedItemLimit = () => {
        if (isMobileLayout()) return mobileCollapsedItems;
        return collapsedRows * getGridColumnCount();
      };

      const resetAllItemsVisibility = () => {
        root.querySelectorAll('.destination-links__item').forEach((el) => {
          el.removeAttribute('hidden');
          el.removeAttribute('aria-hidden');
          el.classList.remove('destination-links__item--clamped');
        });
      };

      /** En mode replié : masque les entrées au-delà de la limite (onglet actif). */
      const applyRowClamp = () => {
        resetAllItemsVisibility();
        if (!body || !body.classList.contains('is-collapsed')) return;

        const activePanel = root.querySelector('.destination-links__panel.is-active');
        if (!activePanel) return;
        const grid = activePanel.querySelector('.destination-links__grid');
        if (!grid) return;

        const maxVisible = getCollapsedItemLimit();
        const items = grid.querySelectorAll('.destination-links__item');
        items.forEach((el, i) => {
          if (i >= maxVisible) {
            el.setAttribute('hidden', '');
            el.setAttribute('aria-hidden', 'true');
            el.classList.add('destination-links__item--clamped');
          }
        });
      };

      const refreshToggleVisibility = () => {
        if (!toggleBtn) return;
        const activePanel = root.querySelector('.destination-links__panel.is-active');
        if (!activePanel) return;
        const grid = activePanel.querySelector('.destination-links__grid');
        if (!grid) return;
        const count = grid.querySelectorAll('.destination-links__item').length;
        const cols = getGridColumnCount();
        let shouldShow;
        if (isMobileLayout()) {
          shouldShow = count > mobileCollapsedItems;
        } else {
          const rowCount = cols > 0 ? Math.ceil(count / cols) : 0;
          shouldShow = rowCount > collapsedRows;
        }
        toggleBtn.style.display = shouldShow ? 'inline-flex' : 'none';
      };

      const scheduleRefresh = () => {
        requestAnimationFrame(() => {
          requestAnimationFrame(() => {
            applyRowClamp();
            refreshToggleVisibility();
          });
        });
      };

      /**
       * Mélange Fisher–Yates sur chaque grille : le `shuffle` Liquid ne tourne qu’au rendu serveur ;
       * avec le cache HTML (boutique / CDN), l’ordre restait identique entre visites.
       */
      const shuffleEachGrid = () => {
        root.querySelectorAll('.destination-links__grid').forEach((grid) => {
          const items = Array.from(grid.children);
          for (let i = items.length - 1; i > 0; i--) {
            const j = Math.floor(Math.random() * (i + 1));
            [items[i], items[j]] = [items[j], items[i]];
          }
          const frag = document.createDocumentFragment();
          items.forEach((el) => frag.appendChild(el));
          grid.appendChild(frag);
        });
      };

      shuffleEachGrid();

      if (toggleBtn && body) {
        toggleBtn.addEventListener('click', () => {
          const isCollapsed = body.classList.contains('is-collapsed');
          body.classList.toggle('is-collapsed', !isCollapsed);
          toggleBtn.textContent = isCollapsed ? 'Afficher moins' : 'Afficher plus';
          applyRowClamp();
          refreshToggleVisibility();
        });
      }

      tabs.forEach((btn) => {
        btn.addEventListener('click', () => {
          const target = btn.getAttribute('data-tab-trigger');

          tabs.forEach((b) => {
            b.classList.toggle('is-active', b === btn);
            b.setAttribute('aria-selected', b === btn ? 'true' : 'false');
          });

          panels.forEach((panel) => {
            panel.classList.toggle('is-active', panel.getAttribute('data-tab-panel') === target);
          });

          if (body) body.classList.add('is-collapsed');
          if (toggleBtn) toggleBtn.textContent = 'Afficher plus';
          scheduleRefresh();
        });
      });

      scheduleRefresh();
      window.addEventListener('resize', scheduleRefresh, { passive: true });
    })();
  </script>
{% endif %}
{% endpaginate %}

