sections/geo-maillage.liquid:
{%- comment -%}
  geo-maillage.liquid (section) — blocs de liens du maillage géo.
  Le fil d'Ariane vit dans sa propre section `geo-fil-ariane`.
  Le contenu vit dans snippets/geo-maillage.liquid.
{%- endcomment -%}
{%- liquid
  assign loven_hide_collection_extra = false
  if request.page_type == 'collection' and current_page > 1
    assign loven_hide_collection_extra = true
  endif
-%}
{%- unless loven_hide_collection_extra -%}
{%- if collection.metafields.geo.maillage.value != blank -%}
  <div class="page-full geo-maillage-section" style="margin-top:{{ section.settings.marge_haut }}px;margin-bottom:{{ section.settings.marge_bas }}px;">
    {%- render 'geo-maillage', bloc: 'liens', prefixe: section.settings.prefixe -%}
  </div>

  <style>
    .geo-maillage__bloc + .geo-maillage__bloc { margin-top: 2.25rem; }
    .geo-maillage__titre {
      font-size: 1.0625rem; line-height: 1.35; margin: 0 0 1rem; font-weight: 600;
    }
    .geo-maillage__liste {
      display: grid; gap: .5rem 1.5rem; margin: 0; padding: 0; list-style: none;
      grid-template-columns: repeat(auto-fill, minmax(210px, 1fr));
    }
    .geo-maillage__item {
      display: flex; align-items: baseline; gap: .4rem;
      font-size: .9375rem; line-height: 1.5;
      padding-bottom: .4rem; border-bottom: 1px solid rgba(0,0,0,.07);
    }
    .geo-maillage__item a { text-decoration: none; }
    .geo-maillage__item a:hover .geo-maillage__zone { text-decoration: underline; text-underline-offset: 2px; }
    .geo-maillage__pre { font-size: .8125rem; opacity: .55; }
    .geo-maillage__zone { font-weight: 600; }
    .geo-maillage__km, .geo-maillage__n {
      margin-left: auto; font-size: .75rem; opacity: .5; white-space: nowrap;
    }
    .geo-maillage__remontee,
    .lns-parent-link { margin: 1.5rem 0 0; font-size: .875rem; }

    @media (max-width: 749px) {
      .geo-maillage__liste { grid-template-columns: repeat(auto-fill, minmax(165px, 1fr)); gap: .4rem 1rem; }
      .geo-maillage__titre { font-size: 1rem; }
      .geo-maillage__item { font-size: .875rem; }
    }
  </style>
{%- endif -%}
{%- endunless -%}

{% schema %}
{
  "name": "Maillage géo",
  "tag": "section",
  "class": "geo-maillage-wrapper",
  "settings": [
    {
      "type": "paragraph",
      "content": "Départements d'une région, villes d'un département, villes proches d'une ville. Aucun lien n'est généré vers une collection vide. À placer juste après la grille produits."
    },
    { "type": "text", "id": "prefixe", "label": "Préfixe des ancres", "default": "Love room", "info": "Porte le mot-clé cible : « Love room Vannes »." },
    { "type": "range", "id": "marge_haut", "label": "Marge haute", "min": 0, "max": 80, "step": 4, "unit": "px", "default": 40 },
    { "type": "range", "id": "marge_bas", "label": "Marge basse", "min": 0, "max": 80, "step": 4, "unit": "px", "default": 40 }
  ],
  "presets": [{ "name": "Maillage géo" }]
}
{% endschema %}

