sections/header.liquid:
{%- liquid
  assign main_menu = linklists[section.settings.main_menu_link_list]

  assign logo_alignment = 'left'
  assign nav_position = 'below'

  if section.settings.main_menu_alignment == 'left' or section.settings.main_menu_alignment == 'left-center'
    assign nav_position = 'beside'
  endif

  if section.settings.main_menu_alignment == 'center'
    assign logo_alignment = 'center'
  endif

  assign template_name = template | replace: '.', ' ' | truncatewords: 2, '' | handle

  assign overlay_header = false
  if template_name == 'index' and section.settings.sticky_index
    assign overlay_header = true
  endif
  if template_name contains 'collection' and collection.image and section.settings.sticky_collection
    assign overlay_header = true
  endif

  assign header_mobile_max_width = 1280
  if template.name == 'index' or template.name == 'collection'
    assign header_mobile_max_width = 1800
  endif
-%}

<style>
  .site-nav__link {
    font-size: {{ settings.type_navigation_size }}px;
  }
  {% if settings.type_navigation_capitalize %}
    .site-nav__link {
      text-transform: uppercase;
      letter-spacing: 0.2em;
    }
  {% endif %}

  {% if mainmenu.length > 6 %}
    .site-nav__link {
      padding-left: 10px;
      padding-right: 10px;
    }
  {% endif %}

  {%- if settings.color_header == settings.color_body_bg or settings.color_body_bg contains settings.color_header -%}
    .site-header,
    .site-header__element--sub {
      box-shadow: 0 0 25px rgb(0 0 0 / 10%);
    }

    .is-light .site-header,
    .is-light .site-header__element--sub {
      box-shadow: none;
    }
  {%- endif -%}

  {%- if settings.color_header == settings.color_header_search -%}
    .site-header__search-form {
      border: 1px solid {{ settings.color_borders }}
    }
  {%- endif -%}

  /* Pleine largeur : uniquement desktop (≥769px). Sur mobile on revient à une largeur type page-width pour rester aligné au contenu. */
  @media only screen and (min-width: 769px) {
    #HeaderWrapper .page-full {
      max-width: none;
      width: 100%;
    }

    #HeaderWrapper .site-nav__dropdown.megamenu {
      left: 0;
      right: 0;
      width: auto;
      min-width: 0;
      max-width: none;
    }

    #HeaderWrapper .site-nav__dropdown.megamenu > .page-full {
      max-width: none;
      width: 100%;
    }

    #HeaderWrapper .megamenu__cols {
      columns: 6;
      flex: 1 1 auto;
    }

    #HeaderWrapper .megamenu__col {
      padding-right: 24px;
    }
  }

  /* Langue : texte + chevron discrets, sans encadré (Markets / Translate & Adapt) */
  #HeaderWrapper .header-language-selector {
    display: inline-flex;
    align-items: center;
    margin-right: 0.35rem;
  }
  #HeaderWrapper .header-language-selector .multi-selectors {
    display: inline-flex;
    justify-content: flex-end;
    margin: 0;
    flex-wrap: nowrap;
  }
  #HeaderWrapper .header-language-selector .multi-selectors__item {
    margin: 0;
  }
  #HeaderWrapper .header-language-selector .disclosure__toggle--header-lang.faux-select {
    display: inline-flex;
    align-items: center;
    gap: 0.2rem;
    min-height: 2.5rem;
    padding: 0.25rem 0.15rem 0.25rem 0.35rem !important;
    margin: 0;
    font-size: 0.8125rem;
    font-weight: 500;
    letter-spacing: normal !important;
    line-height: 1.2;
    color: inherit !important;
    border: none !important;
    border-radius: 0 !important;
    background: transparent !important;
    background-color: transparent !important;
    box-shadow: none;
    appearance: none;
    -webkit-appearance: none;
    cursor: pointer;
    text-align: left;
    text-indent: 0;
  }
  #HeaderWrapper .header-language-selector .disclosure__toggle--header-lang.faux-select:hover,
  #HeaderWrapper .header-language-selector .disclosure__toggle--header-lang.faux-select:focus-visible {
    opacity: 0.85;
  }
  #HeaderWrapper .header-language-selector .disclosure__toggle--header-lang .disclosure-list__label {
    letter-spacing: normal;
    font-weight: 500;
  }
  #HeaderWrapper .header-language-selector .disclosure__toggle--header-lang .header-lang-chevron {
    flex-shrink: 0;
    opacity: 0.65;
    margin-top: 1px;
  }
  #HeaderWrapper .is-light .header-language-selector .disclosure__toggle--header-lang .header-lang-chevron {
    opacity: 0.8;
  }
  #HeaderWrapper .header-language-selector .disclosure-list {
    z-index: 30;
  }

  /* Masquer la recherche dans le header (icône, champs, overlay, ligne mobile, résultats) */
  #HeaderWrapper .header-item--search .site-header__search-form,
  #HeaderWrapper .site-header__search-container,
  #HeaderWrapper .site-header__element--sub[data-type='search'],
  #HeaderWrapper .js-search-header,
  #HeaderWrapper #SearchResultsWrapper {
    display: none !important;
  }

  /*
    Mobile : logo à gauche, panier + menu à droite.
    Si un ancêtre reste en largeur « contenu » (shrink-to-fit), flex/grid ne s’étirent pas — on force toute la chaîne en 100%
    et on ancre les icônes en position absolue sur .header-layout.
  */
  @media only screen and (max-width: 768px) {
    /* Conteneur natif Shopify autour de la section */
    #shopify-section-{{ section.id }} {
      width: 100% !important;
      max-width: 100% !important;
      min-width: 0 !important;
      box-sizing: border-box !important;
    }

    #HeaderWrapper,
    #HeaderWrapper .header-wrapper,
    #HeaderWrapper .site-header,
    #HeaderWrapper .site-header__element--top {
      width: 100% !important;
      max-width: 100% !important;
      min-width: 0 !important;
      box-sizing: border-box !important;
    }

    /* Même gouttière que le reste du site (theme : --pageWidthPadding = 17px sur mobile). Forcé car certains styles écrasent le padding. */
    #HeaderWrapper .site-header__element--top > .page-full {
      width: 100% !important;
      max-width: min(100%, {{ header_mobile_max_width }}px) !important;
      margin-left: auto !important;
      margin-right: auto !important;
      min-width: 0 !important;
      box-sizing: border-box !important;
      padding-left: max(var(--pageWidthPadding, 17px), env(safe-area-inset-left, 0px)) !important;
      padding-right: max(var(--pageWidthPadding, 17px), env(safe-area-inset-right, 0px)) !important;
    }

    #HeaderWrapper .header-layout {
      position: relative !important;
      display: flex !important;
      flex-direction: row !important;
      flex-wrap: nowrap !important;
      align-items: center !important;
      justify-content: flex-start !important;
      width: 100% !important;
      max-width: 100% !important;
      min-width: 0 !important;
      min-height: 56px !important;
      padding-block: 8px !important;
      box-sizing: border-box !important;
    }

    /* Alignement vertical logo / texte (le thème met margin 10px 0 sur .site-header__logo). */
    #HeaderWrapper .site-header__element--top .site-header__logo {
      margin-top: 0 !important;
      margin-bottom: 0 !important;
      display: flex !important;
      align-items: center !important;
    }

    #HeaderWrapper .header-item--compress-nav,
    #HeaderWrapper .header-item--search,
    #HeaderWrapper .header-item--navigation {
      display: none !important;
    }

    #HeaderWrapper .header-item--logo {
      display: flex !important;
      align-items: center !important;
      align-self: center !important;
      width: auto !important;
      max-width: calc(100% - 180px) !important;
      min-width: 0 !important;
      flex: 0 1 auto !important;
      padding-inline-end: 0.5rem !important;
      box-sizing: border-box !important;
    }

    /* Logo centré : le thème force text-align:left sur mobile — on rétablit un centrage propre. */
    #HeaderWrapper .header-layout[data-logo-align='center'] .header-item--logo {
      margin-left: auto !important;
      margin-right: auto !important;
      text-align: center !important;
    }

    #HeaderWrapper .header-layout[data-logo-align='left'] .header-item--logo {
      margin-left: 0 !important;
      margin-right: auto !important;
      text-align: left !important;
    }

    /* Thème : .header-item--icons .site-nav { margin-right: -10px } — colle les icônes au bord. */
    #HeaderWrapper .header-item--icons .site-nav {
      margin-right: 0 !important;
      margin-left: 0 !important;
      margin-inline: 0 !important;
    }

    /* Icônes : même axe vertical que le logo (centre du header-layout). */
    #HeaderWrapper .header-item--icons {
      position: absolute !important;
      inset-inline-end: 0 !important;
      top: 50% !important;
      bottom: auto !important;
      transform: translateY(-50%) !important;
      margin: 0 !important;
      flex: none !important;
      width: auto !important;
      max-width: 200px !important;
      display: flex !important;
      align-items: center !important;
      justify-content: flex-end !important;
      z-index: 2 !important;
    }

    #HeaderWrapper .header-layout[data-logo-align='center'] .header-item--logo,
    #HeaderWrapper .header-layout[data-logo-align='center'] .header-item--icons,
    #HeaderWrapper .header-layout[data-layout='left-center'] .header-item--logo,
    #HeaderWrapper .header-layout[data-layout='left-center'] .header-item--icons {
      flex: none !important;
    }

    #HeaderWrapper .header-item--icons .site-nav__icons {
      justify-content: flex-end !important;
      flex-wrap: nowrap;
      gap: 0.125rem;
    }

    #HeaderWrapper .header-item--icons .site-nav__link--icon {
      padding-inline: 0.35rem !important;
    }

    /* Thème (mobile) : .site-header__logo-link { margin: 0 auto } sur tout le site — à gauche le logo doit rester à gauche. */
    #HeaderWrapper .header-layout[data-logo-align='left'] .site-header__logo-link {
      margin-left: 0 !important;
      margin-right: auto !important;
    }

    #HeaderWrapper .header-layout[data-logo-align='center'] .site-header__logo-link {
      margin-left: auto !important;
      margin-right: auto !important;
    }
  }
</style>

<div data-section-id="{{ section.id }}" data-section-type="header">
  <div id="HeaderWrapper" class="header-wrapper{% if overlay_header %} header-wrapper--overlay is-light{% endif %}">
    <header
      id="SiteHeader"
      class="site-header{% if settings.type_navigation_style == 'heading' %} site-header--heading-style{% endif %}"
      data-sticky="{{ section.settings.header_sticky }}"
      data-overlay="{{ overlay_header }}"
    >
      <div class="site-header__element site-header__element--top">
        <div class="page-full">
          <div
            class="header-layout"
            data-layout="{{ section.settings.main_menu_alignment }}"
            data-nav="{{ nav_position }}"
            data-logo-align="{{ logo_alignment }}"
          >
            {%- if nav_position == 'below' and logo_alignment == 'left' -%}
              <div class="header-item header-item--compress-nav small--hide">
                <button type="button" class="site-nav__link site-nav__link--icon site-nav__compress-menu">
                  <svg
                    aria-hidden="true"
                    focusable="false"
                    role="presentation"
                    class="icon icon-hamburger"
                    viewBox="0 0 64 64"
                  >
                    <path class="cls-1" d="M7 15h51">.</path><path class="cls-1" d="M7 32h43">.</path><path class="cls-1" d="M7 49h51">.</path>
                  </svg>
                  <span class="icon__fallback-text">{{ 'general.drawers.navigation' | t }}</span>
                </button>
              </div>
            {%- endif -%}

            {%- if logo_alignment == 'left' -%}
              <div class="header-item header-item--logo">
                {%- render 'header-logo-block', section: section -%}
              </div>
            {%- endif -%}

            {%- if nav_position == 'below' -%}
              <div class="header-item header-item--search small--hide">
                {%- if logo_alignment == 'center' -%}
                  <button type="button" class="site-nav__link site-nav__link--icon site-nav__compress-menu">
                    <svg
                      aria-hidden="true"
                      focusable="false"
                      role="presentation"
                      class="icon icon-hamburger"
                      viewBox="0 0 64 64"
                    >
                      <path class="cls-1" d="M7 15h51">.</path><path class="cls-1" d="M7 32h43">.</path><path class="cls-1" d="M7 49h51">.</path>
                    </svg>
                    <span class="icon__fallback-text">{{ 'general.drawers.navigation' | t }}</span>
                  </button>
                {%- endif -%}

                {%- render 'header-search' -%}
              </div>
            {%- endif -%}

            {%- if nav_position == 'beside' -%}
              <div class="header-item header-item--navigation{% if section.settings.main_menu_alignment == 'left-center' %} text-center{% endif %}">
                {%- render 'header-desktop-nav',
                  main_menu: main_menu,
                  nav_position: nav_position,
                  show_mega_products: section.settings.mega_products
                -%}
              </div>
            {%- endif -%}

            {%- if logo_alignment == 'center' -%}
              <div class="header-item header-item--logo">
                {%- render 'header-logo-block', section: section -%}
              </div>
            {%- endif -%}

            <div class="header-item header-item--icons">
              {%- render 'header-icons', section: section, nav_position: nav_position -%}
            </div>
          </div>
        </div>

        <div class="site-header__search-container">
          <div class="page-full">
            <div class="site-header__search">
              {%- render 'header-search' -%}
              <button type="button" class="text-link site-header__search-btn site-header__search-btn--cancel">
                <span class="medium-up--hide">
                  <svg
                    aria-hidden="true"
                    focusable="false"
                    role="presentation"
                    class="icon icon-close"
                    viewBox="0 0 64 64"
                  >
                    <defs><style>.cls-1{fill:none;stroke:#000;stroke-miterlimit:10;stroke-width:2px}</style></defs><path class="cls-1" d="M19 17.61l27.12 27.13m0-27.13L19 44.74"/>
                  </svg>
                </span>
                <span class="small--hide">{{ 'general.search.cancel' | t }}</span>
              </button>
            </div>
          </div>
        </div>
      </div>

      {%- if nav_position == 'below' -%}
        <div class="site-header__element site-header__element--sub" data-type="nav">
          <div class="page-full{% if logo_alignment == 'center' %} text-center{% endif %}">
            {%- render 'header-desktop-nav',
              main_menu: main_menu,
              nav_position: nav_position,
              show_mega_products: section.settings.mega_products
            -%}
          </div>
        </div>

        <div class="site-header__element site-header__element--sub" data-type="search">
          <div class="page-full medium-up--hide">
            {%- render 'header-search' -%}
          </div>
        </div>
      {%- endif -%}

      <div class="page-full site-header__drawers">
        <div class="site-header__drawers-container">
          <div class="site-header__drawer site-header__cart" id="HeaderCart">
            <div class="site-header__drawer-animate">
              {%- render 'header-cart-drawer' -%}
            </div>
          </div>

          <div class="site-header__drawer site-header__mobile-nav medium-up--hide" id="MobileNav">
            <div class="site-header__drawer-animate">
              {%- render 'header-mobile-nav', main_menu: main_menu -%}
              {%- if section.settings.header_footer_menu -%}
                <div id="MobileNavFooter"></div>
              {%- endif -%}
            </div>
          </div>
        </div>
      </div>

      {%- if settings.predictive_search_enabled or settings.search_top_collection != blank -%}
        <div id="SearchResultsWrapper" class="site-header__search-results hide">
          {%- if settings.search_top_collection != blank -%}
            {%- assign search_collection = collections[settings.search_top_collection] -%}
            <div id="TopSearched" class="site-header__search-results-wrapper">
              <div class="page-full">
                <div class="h4 site-header__search-title">{{ 'general.search.search_title' | t }}</div>
              </div>
              <div class="page-full page-width--flush-small">
                <div class="new-grid product-grid scrollable-grid--small" data-view="scrollable">
                  {%- for product in search_collection.products limit: 6 -%}
                    {%- render 'product-grid-item', product: product, no_actions: true -%}
                  {%- endfor -%}
                </div>
              </div>
            </div>
          {%- endif -%}

          {%- if settings.predictive_search_enabled -%}
            <div id="PredictiveWrapper" class="hide" data-image-size="{{ settings.predictive_image_size }}">
              <div class="page-full">
                <div id="PredictiveResults" class="predictive-result__layout"></div>
                <div class="text-center predictive-results__footer">
                  <button type="button" class="btn btn--small" data-predictive-search-button>
                    <small>
                      {{ 'general.search.view_more' | t }}
                    </small>
                  </button>
                </div>
              </div>
            </div>
          {%- endif -%}
        </div>
      {%- endif -%}
    </header>
  </div>
</div>

{% schema %}
{
  "name": "t:sections.header.name",
  "class": "header-section",
  "settings": [
    {
      "type": "link_list",
      "id": "main_menu_link_list",
      "label": "t:sections.header.settings.main_menu_link_list.label",
      "default": "main-menu"
    },
    {
      "type": "select",
      "id": "main_menu_alignment",
      "label": "t:sections.header.settings.main_menu_alignment.label",
      "default": "below",
      "options": [
        {
          "value": "below",
          "label": "t:sections.header.settings.main_menu_alignment.options.below.label"
        },
        {
          "value": "left",
          "label": "t:sections.header.settings.main_menu_alignment.options.left.label"
        },
        {
          "value": "left-center",
          "label": "t:sections.header.settings.main_menu_alignment.options.left-center.label"
        },
        {
          "value": "center",
          "label": "t:sections.header.settings.main_menu_alignment.options.center.label"
        }
      ]
    },
    {
      "type": "checkbox",
      "id": "mega_products",
      "label": "t:sections.header.settings.mega_products.label",
      "info": "t:sections.header.settings.mega_products.info",
      "default": true
    },
    {
      "type": "checkbox",
      "id": "header_sticky",
      "label": "t:sections.header.settings.header_sticky.label",
      "default": true,
      "info": "t:sections.header.settings.header_sticky.info"
    },
    {
      "type": "checkbox",
      "id": "header_footer_menu",
      "label": "t:sections.header.settings.header_footer_menu.label",
      "default": true,
      "info": "t:sections.header.settings.header_footer_menu.info"
    },
    {
      "type": "checkbox",
      "id": "sticky_index",
      "label": "t:sections.header.settings.sticky_index.label",
      "default": false
    },
    {
      "type": "checkbox",
      "id": "sticky_collection",
      "label": "t:sections.header.settings.sticky_collection.label",
      "info": "t:sections.header.settings.sticky_collection.info",
      "default": false
    },
    {
      "type": "checkbox",
      "id": "show_header_locale_selector",
      "label": "t:sections.header.settings.show_header_locale_selector.label",
      "info": "t:sections.header.settings.show_header_locale_selector.info",
      "default": true
    }
  ],
  "blocks": [
    {
      "type": "logo",
      "name": "t:sections.header.blocks.logo.name",
      "limit": 1,
      "settings": [
        {
          "type": "image_picker",
          "id": "logo",
          "label": "t:sections.header.blocks.logo.settings.logo.label"
        },
        {
          "type": "image_picker",
          "id": "logo-inverted",
          "label": "t:sections.header.blocks.logo.settings.logo-inverted.label",
          "info": "t:sections.header.blocks.logo.settings.logo-inverted.info"
        },
        {
          "type": "range",
          "id": "desktop_logo_width",
          "label": "t:sections.header.blocks.logo.settings.desktop_logo_width.label",
          "default": 200,
          "min": 100,
          "max": 400,
          "step": 10,
          "unit": "px"
        },
        {
          "type": "range",
          "id": "mobile_logo_width",
          "label": "t:sections.header.blocks.logo.settings.mobile_logo_width.label",
          "default": 140,
          "min": 60,
          "max": 200,
          "step": 10,
          "unit": "px",
          "info": "t:sections.header.blocks.logo.settings.mobile_logo_width.info"
        }
      ]
    }
  ],
  "default": {
    "settings": {}
  }
}
{% endschema %}

sections/hero-video.liquid:
{%- unless section.settings.full_width -%}
  <div class="page-width hero--padded">
{%- endunless -%}

  {%- style -%}
    .hero--{{ section.id }} {
      height: {{ section.settings.height_mobile }}px;
    }
    .hero--{{ section.id }} .hero__title {
      font-size: {{ section.settings.title_size | times: 0.5 }}px;
    }
    @media only screen and (min-width: 769px) {
      .hero--{{ section.id }} {
        height: {{ section.settings.height }}px;
      }
      .hero--{{ section.id }} .hero__title {
        font-size: {{ section.settings.title_size }}px;
      }
    }

    {%- assign button_alpha = section.settings.color_accent | color_extract: 'alpha' -%}
    {% unless button_alpha == 0.0 %}
      .hero--{{ section.id }} .btn {
        background: {{ section.settings.color_accent }} !important;
        border-color: {{ section.settings.color_accent }} !important;

        {%- assign accent_brightness = section.settings.color_accent | color_extract: 'lightness' -%}

        {% if accent_brightness > 40 %}
          color: #000 !important;
        {% endif %}
      }
    {% endunless %}

    {% if section.settings.overlay_opacity > 0 %}
      .hero--{{ section.id }} .hero__text-wrap:after {
        content: '';
        position: absolute;
        left: 0;
        right: 0;
        top: 0;
        bottom: 0;
        z-index: 3;
        background-color: #000;
        opacity: {{ section.settings.overlay_opacity | divided_by: 100.0 }};
      }
    {% endif %}
  {%- endstyle -%}

  <div
