sections/list-collections-villes.liquid:
{%- liquid
  assign loven_hide_collection_extra = false
  if request.page_type == 'collection' and current_page > 1
    assign loven_hide_collection_extra = true
  endif
-%}
{%- unless loven_hide_collection_extra -%}
{{ 'list-collections-villes.css' | asset_url | stylesheet_tag }}

{%- liquid
  # Priorite des sources, de la plus SEO-sure a la moins sure :
  #   1. metafield de page custom.villes_index (json) -> rendu Liquid serveur
  #   2. selecteur manuel ville_collections (max 50)  -> JSON inline + JS
  #   3. API city-collections (Supabase)              -> fetch client, rien dans le HTML servi
  assign villes_index = page.metafields.custom.villes_index.value
  assign use_liquid = false
  if villes_index != blank and villes_index.groups != blank
    assign use_liquid = true
  endif

  assign picker_count = 0
  for _c in section.settings.ville_collections
    assign picker_count = picker_count | plus: 1
  endfor
  assign use_picker = false
  if picker_count > 0
    assign use_picker = true
  endif
-%}

{%- if use_liquid -%}
  {%- comment -%} Page SEO : rien a charger pour afficher, juste le filtre. {%- endcomment -%}
  <script src="{{ 'list-collections-villes-filter.js' | asset_url }}" defer="defer"></script>
{%- else -%}
  <script src="{{ 'list-collections-villes.js' | asset_url }}" defer="defer"></script>
{%- endif -%}

<div class="page-content">
  {%- if section.settings.title_enable -%}
    <div class="page-width">
      <header class="section-header">
        <h1 class="section-header__title">{{ section.settings.title }}</h1>
      </header>
    </div>
  {%- endif -%}

  <div class="page-width page-width--flush-small">
    {%- if use_liquid -%}
      {%- render 'list-collections-villes-liquid',
        section: section,
        villes_index: villes_index
      -%}
    {%- elsif use_picker -%}
      {%- assign picker_collections = section.settings.ville_collections | sort: 'title' -%}
      {%- render 'list-collections-villes-shell',
        section: section,
        picker_collections: picker_collections
      -%}
    {%- else -%}
      {%- render 'list-collections-villes-shell', section: section -%}
    {%- endif -%}
  </div>
</div>
{%- endunless -%}

{% schema %}
{
  "name": "t:sections.list-collections-villes.name",
