<script>
(function(){
  var root=document.getElementById('ll2'); if(!root) return;
  var live=root.querySelector('[data-ll2-live]');
  root.addEventListener('click',function(e){
    var a=e.target.closest('a[data-ll2-model]');
    if(a){
      var p={model:a.getAttribute('data-ll2-model'),placement:a.getAttribute('data-ll2-place'),partner:'lelo'};
      try{ if(window.gtag) gtag('event','affiliate_click',p); else (window.dataLayer=window.dataLayer||[]).push(Object.assign({event:'affiliate_click'},p)); }catch(err){}
      try{ if(window.fbq) fbq('trackCustom','AffiliateClick',p); }catch(err){}
      return;
    }
    var btn=e.target.closest('[data-ll2-copy]'); if(!btn) return;
    var code=btn.getAttribute('data-ll2-copy');
    var done=function(){
      var l=btn.querySelector('[data-ll2-copy-label]'); var old=l.getAttribute('data-old')||l.textContent;
      l.setAttribute('data-old',old); l.textContent='Copié'; btn.classList.add('is-copied');
      if(live) live.textContent='Code '+code+' copié';
      setTimeout(function(){ l.textContent=old; btn.classList.remove('is-copied'); },2200);
    };
    var fallback=function(){ var t=document.createElement('textarea'); t.value=code; t.setAttribute('readonly',''); t.style.position='absolute'; t.style.left='-9999px'; document.body.appendChild(t); t.select(); try{ if(document.execCommand('copy')) done(); }catch(err){} t.remove(); };
    if(navigator.clipboard&&navigator.clipboard.writeText){ navigator.clipboard.writeText(code).then(done,fallback); } else { fallback(); }
  });
  var bar=root.querySelector('[data-ll2-bar]'), heroCta=root.querySelector('.ll2-hero .ll2-btn-primary'), finalSec=root.querySelector('[aria-labelledby="ll2-final-t"]');
  if(bar&&heroCta&&'IntersectionObserver' in window){
    var heroOut=false, finalIn=false;
    var upd=function(){ var on=heroOut&&!finalIn; bar.classList.toggle('is-on',on); bar.setAttribute('aria-hidden',on?'false':'true'); bar.querySelector('button').tabIndex=on?0:-1; };
    new IntersectionObserver(function(en){ heroOut=!en[0].isIntersecting&&en[0].boundingClientRect.top<0; upd(); }).observe(heroCta);
    if(finalSec) new IntersectionObserver(function(en){ finalIn=en[0].isIntersecting; upd(); }).observe(finalSec);
  }
})();
</script>

