      <div class="lns-car__head"><div class="lns-car__titles"><h2 class="lns-car__title">{{ section.settings.title | escape }}</h2></div></div>
    {%- endif -%}
    <div class="lns-faq">
      <div class="lns-faq__col">
      {%- assign lns_i = 0 -%}
      {%- for block in section.blocks -%}
        {%- if block.type == 'question' and block.settings.title != blank and block.settings.text != blank -%}
          {%- if lns_i == lns_moitie -%}</div><div class="lns-faq__col">{%- endif -%}
          <details class="lns-faq__q" {{ block.shopify_attributes }}{% if lns_i == 0 and section.settings.first_open %} open{% endif %}>
            <summary class="lns-faq__summary"><span>{{ block.settings.title | escape }}</span><svg class="lns-faq__icon" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" aria-hidden="true" focusable="false"><path class="lns-faq__v" d="M12 5v14"/><path d="M5 12h14"/></svg></summary>
            <div class="lns-faq__a">{{ block.settings.text }}</div>
          </details>
          {%- assign lns_i = lns_i | plus: 1 -%}
        {%- endif -%}
      {%- endfor -%}
      </div>
    </div>
  </div>
</div>
<script type="application/ld+json">
  {
    "@context": "https://schema.org",
    "@type": "FAQPage",
    "mainEntity": [
      {%- assign lns_j = 0 -%}
      {%- for block in section.blocks -%}
        {%- if block.type == 'question' and block.settings.title != blank and block.settings.text != blank -%}
          {%- if lns_j > 0 -%},{%- endif -%}
          {
            "@type": "Question",
            "name": {{ block.settings.title | json }},
            "acceptedAnswer": { "@type": "Answer", "text": {{ block.settings.text | json }} }
          }
          {%- assign lns_j = lns_j | plus: 1 -%}
        {%- endif -%}
      {%- endfor -%}
    ]
  }
</script>
{%- endif -%}

