sections/loven-proximite.liquid:
{%- comment -%}
  sections/loven-proximite.liquid
  Module anti cul-de-sac de la fiche produit, format carrousel type Airbnb.
  5 cartes visibles sur desktop, jusqu'a 10 rooms dans le carrousel.
  Zone resolue depuis les metaobjets : ville, sinon departement, sinon region.
  Le decalage change chaque jour pour que toutes les rooms de la zone
  passent en vitrine a tour de role.
{%- endcomment -%}

{%- liquid
  assign region_name = product.metafields.custom.region_collection.value.region.value | default: ''

  assign dept_name = ''
  assign dept_list = product.metafields.custom.departement_list.value
  if dept_list != blank
    assign dept_mo = dept_list | first
    assign dept_name = dept_mo.name.value | default: ''
  endif

  comment
    accentuate.ville porte la ville de rattachement collection (Chambery),
    pas la commune reelle qui est dans accentuate.city (Tresserve).
  endcomment
  assign ville_name = product.metafields.accentuate.ville | default: ''

  assign region_h = region_name | handleize
  assign dept_h = dept_name | handleize
  assign ville_h = ville_name | handleize

  assign region_handle = ''
  assign dept_handle = ''
  assign ville_handle = ''

  for c in product.collections
    assign ch = c.title | handleize
    if region_handle == blank and region_h != blank and ch == region_h
      assign region_handle = c.handle
    endif
    if dept_handle == blank and dept_h != blank and ch == dept_h
      assign dept_handle = c.handle
    endif
    if ville_handle == blank and ville_h != blank and ch == ville_h
      assign ville_handle = c.handle
    endif
  endfor

  if ville_handle == blank
    for mo in product.metafields.custom.ville_collection_list.value
      assign mh = mo.name.value | handleize
      for c in product.collections
        assign ch = c.title | handleize
        if ville_handle == blank and ch == mh
          assign ville_handle = c.handle
        endif
      endfor
    endfor
  endif

  assign lim = section.settings.count | default: 10
  assign seuil = section.settings.min_zone | default: 4

  assign zone = collections[ville_handle]
  if zone == blank or zone.products_count < seuil
    assign zone = collections[dept_handle]
  endif
  if zone == blank or zone.products_count < seuil
    assign zone = collections[region_handle]
  endif

  comment
    Rotation quotidienne. Rappel : collection.products est plafonne a 50
    dans une boucle for sans paginate.
  endcomment
  assign pool = zone.products_count | default: 0
  if pool > 50
    assign pool = 50
  endif
  assign span = pool | minus: lim | minus: 1
  assign offset = 0
  if span > 0
    assign seed = 'now' | date: '%j' | plus: 0
    assign offset = seed | modulo: span
  endif
  assign fetch = lim | plus: 2

  assign theme_list = section.settings.collections_theme | split: ','
  assign theme_keys = ','
  for h in theme_list
    assign hh = h | strip
    assign theme_keys = theme_keys | append: hh | append: ','
  endfor
-%}

{%- if zone != blank and zone.products_count > 1 -%}
  <div class="lvn-prox index-section" id="lvn-prox-{{ section.id }}">
    <div class="page-width">
      <div class="lvn-prox__head">
        <div class="lvn-prox__head-text">
          <h2 class="h3 lvn-prox__title">{{ section.settings.heading }}</h2>
          <a class="lvn-prox__all" href="{{ zone.url }}" data-loven-link="proximite-voir-tout">
            {{ zone.title }} &middot; {{ zone.products_count }} love rooms
          </a>
        </div>

        <div class="lvn-prox__nav" aria-hidden="true">
          <button type="button" class="lvn-prox__arrow" data-lvn-dir="-1" aria-label="Precedent">
            <svg viewBox="0 0 24 24" width="16" height="16" focusable="false"><path d="M15 4 7 12l8 8" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>
          </button>
          <button type="button" class="lvn-prox__arrow" data-lvn-dir="1" aria-label="Suivant">
            <svg viewBox="0 0 24 24" width="16" height="16" focusable="false"><path d="M9 4l8 8-8 8" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>
          </button>
        </div>
      </div>

      <div class="lvn-prox__track" data-lvn-track tabindex="0" role="group" aria-label="{{ section.settings.heading | escape }}">
        {%- assign shown = 0 -%}
        {%- assign seen = ',' -%}

        {%- for p in zone.products limit: fetch offset: offset -%}
          {%- if p.id != product.id and p.template_suffix != 'produit-churn' and shown < lim -%}
            {%- assign shown = shown | plus: 1 -%}
            {%- assign seen = seen | append: p.id | append: ',' -%}
            <div class="lvn-prox__slide">
              {%- render 'product-grid-item', product: p, grid_image_index: 99, no_actions: true, classes: 'lvn-prox__card' -%}
            </div>
          {%- endif -%}
        {%- endfor -%}

        {%- if shown < lim -%}
          {%- for p in zone.products limit: 24 -%}
            {%- assign key = ',' | append: p.id | append: ',' -%}
            {%- unless seen contains key -%}
              {%- if p.id != product.id and p.template_suffix != 'produit-churn' and shown < lim -%}
                {%- assign shown = shown | plus: 1 -%}
                {%- assign seen = seen | append: p.id | append: ',' -%}
                <div class="lvn-prox__slide">
                  {%- render 'product-grid-item', product: p, grid_image_index: 99, no_actions: true, classes: 'lvn-prox__card' -%}
                </div>
              {%- endif -%}
            {%- endunless -%}
          {%- endfor -%}
        {%- endif -%}
      </div>

      {%- if section.settings.show_themes -%}
        {%- assign theme_count = 0 -%}
        {%- capture theme_links -%}
          {%- for c in product.collections -%}
            {%- assign key = ',' | append: c.handle | append: ',' -%}
            {%- if theme_keys contains key and theme_count < 5 -%}
              {%- assign theme_count = theme_count | plus: 1 -%}
              <a class="lvn-prox__chip" href="{{ c.url }}" data-loven-link="proximite-theme">{{ c.title }}</a>
            {%- endif -%}
          {%- endfor -%}
          {%- if dept_handle != blank and zone.handle != dept_handle -%}
            <a class="lvn-prox__chip" href="{{ collections[dept_handle].url }}" data-loven-link="proximite-departement">Tout le {{ collections[dept_handle].title }}</a>
          {%- endif -%}
        {%- endcapture -%}

        {%- if theme_links != blank -%}
          <div class="lvn-prox__themes">
            <p class="lvn-prox__themes-label">Explorer autrement</p>
            <div class="lvn-prox__chips">{{ theme_links }}</div>
          </div>
        {%- endif -%}
      {%- endif -%}
    </div>
  </div>

  <style>
    #lvn-prox-{{ section.id }}.lvn-prox{
      padding:40px 0;
      background:#FFFFFF;
      font-family:Poppins,sans-serif;
      --lvn-gap:16px;
      --lvn-per-view:5;
    }
    #lvn-prox-{{ section.id }} .lvn-prox__head{
      display:flex;align-items:flex-end;justify-content:space-between;gap:16px;margin-bottom:20px;
    }
    #lvn-prox-{{ section.id }} .lvn-prox__title{margin:0 0 4px;color:#222222}
    #lvn-prox-{{ section.id }} .lvn-prox__all{
      font-size:14px;font-weight:700;color:#E83F4E;text-decoration:none;border-bottom:1px solid #E83F4E;
    }
    #lvn-prox-{{ section.id }} .lvn-prox__nav{display:flex;gap:8px;flex:0 0 auto}
    #lvn-prox-{{ section.id }} .lvn-prox__arrow{
      display:inline-flex;align-items:center;justify-content:center;
      width:36px;height:36px;padding:0;
      border:1px solid #EBE5E0;border-radius:999px;background:#FFFFFF;color:#222222;
      cursor:pointer;transition:border-color .15s,color .15s,opacity .15s;
    }
    #lvn-prox-{{ section.id }} .lvn-prox__arrow:hover{border-color:#E83F4E;color:#E83F4E}
    #lvn-prox-{{ section.id }} .lvn-prox__arrow[disabled]{opacity:.3;cursor:default}
    #lvn-prox-{{ section.id }} .lvn-prox__arrow:hover[disabled]{border-color:#EBE5E0;color:#222222}

    #lvn-prox-{{ section.id }} .lvn-prox__track{
      display:flex;
      gap:var(--lvn-gap);
      overflow-x:auto;
      overflow-y:hidden;
      scroll-snap-type:x mandatory;
      scroll-behavior:smooth;
      scrollbar-width:none;
      -webkit-overflow-scrolling:touch;
      padding-bottom:4px;
    }
    #lvn-prox-{{ section.id }} .lvn-prox__track::-webkit-scrollbar{display:none}
    #lvn-prox-{{ section.id }} .lvn-prox__track:focus-visible{outline:2px solid #E83F4E;outline-offset:4px}

    #lvn-prox-{{ section.id }} .lvn-prox__slide{
      flex:0 0 calc((100% - (var(--lvn-per-view) - 1) * var(--lvn-gap)) / var(--lvn-per-view));
      scroll-snap-align:start;
      min-width:0;
    }
    #lvn-prox-{{ section.id }} .lvn-prox__slide .grid-item{width:100%;margin:0;padding:0}

    #lvn-prox-{{ section.id }} .lvn-prox__themes{
      margin-top:28px;padding-top:20px;border-top:1px solid #EBE5E0;
    }
    #lvn-prox-{{ section.id }} .lvn-prox__themes-label{
      margin:0 0 12px;font-size:13px;font-weight:700;color:#6c6c6c;text-transform:uppercase;letter-spacing:.04em;
    }
    #lvn-prox-{{ section.id }} .lvn-prox__chips{display:flex;flex-wrap:wrap;gap:8px}
    #lvn-prox-{{ section.id }} .lvn-prox__chip{
      display:inline-block;padding:8px 16px;
      border:1px solid #EBE5E0;border-radius:999px;background:#FFFFFF;color:#222222;
      font-size:13px;text-decoration:none;
    }
    #lvn-prox-{{ section.id }} .lvn-prox__chip:hover{border-color:#E83F4E;color:#E83F4E}

    @media (max-width:1199px){
      #lvn-prox-{{ section.id }}.lvn-prox{--lvn-per-view:4}
    }
    @media (max-width:989px){
      #lvn-prox-{{ section.id }}.lvn-prox{--lvn-per-view:3;--lvn-gap:12px}
      #lvn-prox-{{ section.id }} .lvn-prox__nav{display:none}
    }
    @media (max-width:749px){
      #lvn-prox-{{ section.id }}.lvn-prox{padding:28px 0;--lvn-per-view:1.35;--lvn-gap:12px}
      #lvn-prox-{{ section.id }} .lvn-prox__head{align-items:flex-start;margin-bottom:16px}
      #lvn-prox-{{ section.id }} .lvn-prox__all{font-size:13px}
    }
  </style>

  <script>
    (function () {
      var root = document.getElementById('lvn-prox-{{ section.id }}');
      if (!root) return;
      var track = root.querySelector('[data-lvn-track]');
      var arrows = root.querySelectorAll('[data-lvn-dir]');
      if (!track || !arrows.length) return;

      function step() {
        var slide = track.querySelector('.lvn-prox__slide');
        if (!slide) return track.clientWidth;
        var gap = parseFloat(getComputedStyle(track).columnGap || '16') || 16;
        return (slide.getBoundingClientRect().width + gap) * Math.max(1, Math.floor(track.clientWidth / (slide.getBoundingClientRect().width + gap)) - 1);
      }

      function refresh() {
        var max = track.scrollWidth - track.clientWidth - 2;
        arrows.forEach(function (btn) {
          var dir = parseInt(btn.getAttribute('data-lvn-dir'), 10);
          btn.disabled = dir < 0 ? track.scrollLeft <= 2 : track.scrollLeft >= max;
        });
      }

      arrows.forEach(function (btn) {
        btn.addEventListener('click', function () {
          track.scrollBy({ left: parseInt(btn.getAttribute('data-lvn-dir'), 10) * step(), behavior: 'smooth' });
        });
      });

      track.addEventListener('scroll', refresh, { passive: true });
      window.addEventListener('resize', refresh);
      refresh();
    })();
  </script>
{%- endif -%}

