sections/magazine-home.liquid:
{%- comment -%}
  Page d'accueil du Magazine, façon presse.

  Classement des articles, piloté par deux métafields JSON du blog (listes de handles) :
  - custom.articles_classiques : articles de l'équipe (Une, cartes en tête des pages 2+) ;
  - custom.articles_hebergeurs : articles pour les hébergeurs (bandeau, vue ?view=hebergeurs) ;
  - tout le reste (Holo) va dans le fil « Toutes nos lectures ». Un nouvel article Holo y tombe donc tout seul.

  Page 1 : Une (cochés « À la une » puis équipe), bandeau hébergeurs, fil de la tranche paginée.
  Pages 2+ : suite des articles de l'équipe en cartes, puis le fil de la tranche.
  Vues filtrées par tag : articles de l'équipe de la tranche en cartes, le reste en fil.
{%- endcomment -%}
{{ 'magazine-home.css' | asset_url | stylesheet_tag }}

{%- liquid
  assign mg_tagged = false
  if current_tags != blank
    assign mg_tagged = true
  endif
  assign mg_une_max = section.settings.une_count
  # Liste JSON des handles des articles de l'équipe (sans préfixe de blog), tenue à jour par la tâche quotidienne
  assign mg_list = blog.metafields.custom.articles_classiques.value
  assign mg_list_size = mg_list.size | default: 0
  # Chaînes ',h1,h2,' pour des tests d'appartenance fiables
  assign mg_cls_str = ''
  if mg_list_size > 0
    assign mg_cls_str = mg_list | join: ','
  endif
  assign mg_cls_str = ',' | append: mg_cls_str | append: ','
  assign mg_heb = blog.metafields.custom.articles_hebergeurs.value
  assign mg_heb_size = mg_heb.size | default: 0
  assign mg_prefix = blog.handle | append: '/'

  # Une de la page 1 (calculée sur toutes les pages pour éviter les doublons) :
  # d'abord les articles cochés « À la une » parmi les 50 plus récents, puis les articles de l'équipe de la liste
  assign mg_p1 = ','
  assign mg_p1_order = ''
  assign mg_p1_total = 0
  assign mg_cls_used = 0
  unless mg_tagged
    for a in blog.articles limit: 50
      if mg_p1_total >= mg_une_max
        break
      endif
      assign a_take = false
      if a.metafields.custom.a_la_une.value == true
        assign a_take = true
      elsif mg_list_size == 0
        assign a_take = true
        if a.author == 'Admin'
          assign a_take = false
        endif
      endif
      if a_take
        assign a_h = a.handle | split: '/' | last
        assign mg_p1 = mg_p1 | append: a_h | append: ','
        assign mg_p1_order = mg_p1_order | append: a_h | append: ','
        assign mg_p1_total = mg_p1_total | plus: 1
      endif
    endfor
    if mg_list_size > 0
      for h in mg_list
        if mg_p1_total >= mg_une_max
          break
        endif
        assign mg_cls_used = mg_cls_used | plus: 1
        assign a_key = ',' | append: h | append: ','
        if mg_p1 contains a_key
          continue
        endif
        # Handle périmé (article dépublié ou supprimé) : on continue la liste
        # au lieu de le compter. Sinon le premier slot, vide, empêche la Une
        # et la grille, et le </div> de fermeture casse les colonnes.
        assign mg_try_key = mg_prefix | append: h
        assign mg_try_article = articles[mg_try_key]
        if mg_try_article == blank
          continue
        endif
        assign mg_p1 = mg_p1 | append: h | append: ','
        assign mg_p1_order = mg_p1_order | append: h | append: ','
        assign mg_p1_total = mg_p1_total | plus: 1
      endfor
    endif
  endunless
  assign mg_p1_list = mg_p1_order | split: ','

  # Bandeau hébergeurs (page 1 uniquement) : les 2 plus récents
  assign mg_biz = ','
  assign mg_biz_total = 0
  if section.settings.show_business and mg_tagged == false and mg_heb_size > 0
    for h in mg_heb
      if mg_biz_total >= 2
        break
      endif
      assign a_key = ',' | append: h | append: ','
      if mg_p1 contains a_key
        continue
      endif
      assign mg_try_key = mg_prefix | append: h
      assign mg_try_article = articles[mg_try_key]
      if mg_try_article == blank
        continue
      endif
      assign mg_biz_total = mg_biz_total | plus: 1
      assign mg_biz = mg_biz | append: h | append: ','
    endfor
  endif
  assign mg_biz_list = mg_biz | split: ','

  assign mg_is_p1 = false
  if current_page == 1 and mg_tagged == false
    assign mg_is_p1 = true
  endif

  assign mg_has_promo = false
  for block in section.blocks
    if block.type == 'liquid'
      assign mg_has_promo = true
      break
    endif
  endfor

  assign mg_has_aside = false
  if section.blocks.size > 0 or section.settings.cta_label != blank
    assign mg_has_aside = true
  endif
-%}

<div class="mg" data-section-id="{{ section.id }}">
  {%- if template.suffix == 'hebergeurs' -%}
    <section class="mg-sec" aria-labelledby="mg-heb-{{ section.id }}">
      <div class="mg-sec__head"><h2 id="mg-heb-{{ section.id }}">{{ section.settings.business_heading | escape }}</h2><a class="mg-sec__all" href="{{ blog.url }}">Tout le Magazine<span aria-hidden="true"> →</span></a></div>
      {%- if section.settings.business_intro != blank -%}<p class="mg-pros__intro">{{ section.settings.business_intro | escape }}</p>{%- endif -%}
      <div class="mg-grid">
        {%- for h in mg_heb -%}
          {%- assign mg_key = mg_prefix | append: h -%}
          {%- assign a = articles[mg_key] -%}
          {%- if a == blank -%}{%- continue -%}{%- endif -%}
          {%- render 'magazine-card', article: a -%}
        {%- endfor -%}
      </div>
    </section>
  {%- else -%}
  {%- comment -%} Une et bandeau hors paginate : dans paginate, blog.articles ne contient que la page courante {%- endcomment -%}
    {%- if mg_is_p1 and mg_p1_total > 0 -%}
      {%- comment -%} Page 1 : la Une {%- endcomment -%}
      <section class="mg-sec" aria-labelledby="mg-une-{{ section.id }}">
        <div class="mg-sec__head"><h2 id="mg-une-{{ section.id }}">{{ section.settings.une_heading | escape }}</h2></div>
        <div class="mg-une{% unless mg_has_promo %} mg-une--full{% endunless %}">
          <div class="mg-une__main">
          {%- assign mg_lead_done = false -%}
          {%- assign mg_grid_opened = false -%}
          {%- for h in mg_p1_list -%}
            {%- assign mg_key = mg_prefix | append: h -%}
            {%- assign a = articles[mg_key] -%}
            {%- if a == blank -%}{%- continue -%}{%- endif -%}
            {%- if mg_lead_done == false -%}
              {%- liquid
                assign mg_img = a.metafields.custom.image_une.value | default: a.image
                assign mg_kicker = ''
                for t in a.tags
                  assign t_first = t | slice: 0
                  if t_first != '_'
                    assign mg_kicker = t
                    break
                  endif
                endfor
                assign mg_chapo = a.excerpt | strip_html | strip
                if mg_chapo == blank
                  assign mg_chapo = a.content | strip_html | strip | truncatewords: 40
                endif
                assign mg_lead_done = true
              -%}
              <article class="mg-lead">
                <a href="{{ a.url }}" class="mg-lead__link mg-ph mg-ph--lead" tabindex="-1" aria-hidden="true">
                  {%- if mg_img != blank -%}
                    {{ mg_img | image_url: width: 1600 | image_tag: loading: 'eager', fetchpriority: 'high', sizes: '(min-width: 990px) 60vw, 100vw', widths: '600, 900, 1200, 1600', alt: a.title }}
                  {%- endif -%}
                </a>
                <div class="mg-lead__body">
                  {%- if mg_kicker != blank -%}<span class="mg-kicker">{{ mg_kicker | escape }}</span>{%- endif -%}
                  <h3 class="mg-lead__title"><a href="{{ a.url }}">{{ a.title | escape }}</a></h3>
                  {%- if mg_chapo != blank -%}<p class="mg-lead__chapo">{{ mg_chapo | escape }}</p>{%- endif -%}
                  <a href="{{ a.url }}" class="mg-lead__more">Lire l'article<span aria-hidden="true"> →</span></a>
                </div>
              </article>
              {%- if mg_p1_total > 1 -%}
                <div class="mg-une__grid">
                {%- assign mg_grid_opened = true -%}
              {%- endif -%}
            {%- else -%}
              {%- render 'magazine-card', article: a, sizes: '(min-width: 990px) 22vw, (min-width: 640px) 45vw, 110px' -%}
            {%- endif -%}
          {%- endfor -%}
          {%- if mg_grid_opened -%}</div>{%- endif -%}
          </div>
          {%- if mg_has_promo -%}
            <aside class="mg-une__promo" aria-label="Offres partenaires">
              {%- for block in section.blocks -%}
                {%- if block.type == 'liquid' -%}
                  <div class="mg-aside__extra" {{ block.shopify_attributes }}>{{ block.settings.liquid }}</div>
                {%- endif -%}
              {%- endfor -%}
            </aside>
          {%- endif -%}
        </div>
      </section>
    {%- endif -%}

    {%- if mg_is_p1 and mg_biz_total > 0 -%}
      {%- comment -%} Bandeau hébergeurs, page 1 uniquement, entre la Une et le fil {%- endcomment -%}
      <section class="mg-sec mg-pros" aria-labelledby="mg-pros-{{ section.id }}">
        <div class="mg-sec__head"><h2 id="mg-pros-{{ section.id }}">{{ section.settings.business_heading | escape }}</h2><a class="mg-sec__all" href="{{ blog.url }}?view=hebergeurs">{{ section.settings.business_all_label | escape }}<span aria-hidden="true"> →</span></a></div>
        {%- if section.settings.business_intro != blank -%}<p class="mg-pros__intro">{{ section.settings.business_intro | escape }}</p>{%- endif -%}
        <div class="mg-pros__grid">
          {%- for h in mg_biz_list -%}
            {%- assign mg_key = mg_prefix | append: h -%}
            {%- assign a = articles[mg_key] -%}
            {%- if a == blank -%}{%- continue -%}{%- endif -%}
            <a class="mg-pro" href="{{ a.url }}">
              <div class="mg-ph mg-ph--pro">
                {%- if a.image -%}{{ a.image | image_url: width: 480 | image_tag: loading: 'lazy', sizes: '200px', widths: '240, 360, 480', alt: a.title }}{%- endif -%}
              </div>
              <h3 class="mg-pro__title">{{ a.title | escape }}</h3>
            </a>
          {%- endfor -%}
        </div>
      </section>
    {%- endif -%}

  {%- paginate blog.articles by section.settings.per_page -%}
    {%- liquid
      assign mg_page = paginate.current_page
      assign mg_is_p1 = false
      if mg_page == 1 and mg_tagged == false
        assign mg_is_p1 = true
      endif
    -%}

    {%- if mg_tagged == false and mg_page > 1 and mg_list_size > 0 -%}
      {%- comment -%} Pages 2+ : la suite des classiques (métafield de blog articles_classiques), répartie sur toutes les pages {%- endcomment -%}
      {%- liquid
        assign mg_rest = mg_list_size | minus: mg_cls_used
        assign mg_other_pages = paginate.pages | minus: 1
        if mg_other_pages < 1
          assign mg_other_pages = 1
        endif
        assign mg_per = mg_rest | plus: mg_other_pages | minus: 1 | divided_by: mg_other_pages
        if mg_per < 1
          assign mg_per = 1
        endif
        assign mg_off = mg_page | minus: 2 | times: mg_per | plus: mg_cls_used
      -%}
      {%- if mg_off < mg_list_size -%}
        <section class="mg-sec" aria-label="Articles de la rédaction">
          <div class="mg-grid">
            {%- for h in mg_list offset: mg_off limit: mg_per -%}
              {%- assign a_key = ',' | append: h | append: ',' -%}
              {%- if mg_p1 contains a_key -%}{%- continue -%}{%- endif -%}
              {%- assign mg_key = mg_prefix | append: h -%}
              {%- assign a = articles[mg_key] -%}
              {%- if a == blank -%}{%- continue -%}{%- endif -%}
              {%- render 'magazine-card', article: a -%}
            {%- endfor -%}
          </div>
        </section>
      {%- endif -%}

    {%- elsif mg_tagged or mg_list_size == 0 -%}
      {%- comment -%} Vue par tag, ou liste pas encore créée : classiques de la tranche en cartes {%- endcomment -%}
      {%- liquid
        assign mg_slice_cards = 0
        for a in blog.articles
          assign a_h = a.handle | split: '/' | last
          assign a_key = ',' | append: a_h | append: ','
          if mg_list_size > 0
            unless mg_cls_str contains a_key
              continue
            endunless
          elsif a.author == 'Admin'
            continue
          endif
          if mg_p1 contains a_key
            continue
          endif
          assign mg_slice_cards = mg_slice_cards | plus: 1
        endfor
      -%}
      {%- if mg_slice_cards > 0 -%}
        <section class="mg-sec" aria-label="Articles de la rédaction">
          <div class="mg-grid">
            {%- for a in blog.articles -%}
              {%- assign a_h = a.handle | split: '/' | last -%}{%- assign a_key = ',' | append: a_h | append: ',' -%}
              {%- if mg_list_size > 0 -%}
                {%- unless mg_cls_str contains a_key -%}{%- continue -%}{%- endunless -%}
              {%- elsif a.author == 'Admin' -%}{%- continue -%}{%- endif -%}
              {%- if mg_p1 contains a_key -%}{%- continue -%}{%- endif -%}
              {%- render 'magazine-card', article: a -%}
            {%- endfor -%}
          </div>
        </section>
      {%- endif -%}
    {%- endif -%}

    {%- comment -%} Fil : Holo et hébergeurs de la tranche, jamais les classiques {%- endcomment -%}
    {%- liquid
      assign mg_fil_count = 0
      for a in blog.articles
        assign a_h = a.handle | split: '/' | last
        assign a_key = ',' | append: a_h | append: ','
        if mg_p1 contains a_key
          continue
        endif
        if mg_biz contains a_key
          continue
        endif
        if mg_list_size > 0
          unless mg_cls_str contains a_key
            assign mg_fil_count = mg_fil_count | plus: 1
          endunless
        elsif a.author == 'Admin'
          assign mg_fil_count = mg_fil_count | plus: 1
        endif
      endfor
    -%}

    <section class="mg-sec" id="mg-fil" aria-labelledby="mg-fil-{{ section.id }}">
      {%- if mg_fil_count > 0 -%}
        <div class="mg-sec__head">
          <h2 id="mg-fil-{{ section.id }}">
            {%- if mg_tagged -%}{{ current_tags | join: ', ' | escape }}{%- else -%}{{ section.settings.fil_heading | escape }}{%- endif -%}
          </h2>
        </div>
      {%- endif -%}
      <div class="mg-fil-layout{% unless mg_has_aside %} mg-fil-layout--full{% endunless %}">
        <div>
          {%- if mg_fil_count > 0 -%}
            <ul class="mg-fil">
              {%- for article in blog.articles -%}
                {%- liquid
                  assign a_h = article.handle | split: '/' | last
                  assign a_key = ',' | append: a_h | append: ','
                  if mg_p1 contains a_key
                    continue
                  endif
                  if mg_biz contains a_key
                    continue
                  endif
                  assign a_fil = false
                  if mg_list_size > 0
                    unless mg_cls_str contains a_key
                      assign a_fil = true
                    endunless
                  elsif article.author == 'Admin'
                    assign a_fil = true
                  endif
                  unless a_fil
                    continue
                  endunless
                -%}
                {%- render 'magazine-fil-item', article: article, show_filet: section.settings.show_filet -%}
              {%- endfor -%}
            </ul>
          {%- endif -%}
          {%- if paginate.pages > 1 -%}
            <div class="mg-pagination">{%- render 'pagination', paginate: paginate -%}</div>
          {%- endif -%}
        </div>

        {%- if mg_has_aside -%}
          <aside class="mg-aside">
            <div class="mg-aside__box">
              {%- if section.settings.cta_heading != blank -%}<h4 class="mg-aside__title">{{ section.settings.cta_heading | escape }}</h4>{%- endif -%}
              {%- if section.settings.cta_text != blank -%}<p class="mg-aside__text">{{ section.settings.cta_text | escape }}</p>{%- endif -%}
              {%- if section.settings.cta_label != blank and section.settings.cta_url != blank -%}
                <a class="mg-btn" href="{{ section.settings.cta_url }}">{{ section.settings.cta_label | escape }}</a>
              {%- endif -%}
              {%- assign mg_has_links = false -%}
              {%- for block in section.blocks -%}{%- if block.type == 'lien' -%}{%- assign mg_has_links = true -%}{%- endif -%}{%- endfor -%}
              {%- if mg_has_links -%}
                <ul class="mg-aside__links">
                  {%- for block in section.blocks -%}
                    {%- if block.type == 'lien' and block.settings.label != blank -%}
                      <li {{ block.shopify_attributes }}><a href="{{ block.settings.url }}">{{ block.settings.label | escape }}<span aria-hidden="true">→</span></a></li>
                    {%- endif -%}
                  {%- endfor -%}
                </ul>
              {%- endif -%}
            </div>
            {%- unless mg_is_p1 and mg_p1_total > 0 -%}
              {%- for block in section.blocks -%}
                {%- if block.type == 'liquid' -%}
                  <div class="mg-aside__extra" {{ block.shopify_attributes }}>{{ block.settings.liquid }}</div>
                {%- endif -%}
              {%- endfor -%}
            {%- endunless -%}
          </aside>
        {%- endif -%}
      </div>
    </section>

  {%- endpaginate -%}
  {%- endif -%}
</div>

{% schema %}
{
  "name": "Magazine : accueil presse",
  "class": "mg-section-wrap",
  "settings": [
    { "type": "header", "content": "La Une" },
    { "type": "paragraph", "content": "Page 1 : articles cochés « À la une » puis articles de l'équipe les plus récents. Pages suivantes : la suite des articles de l'équipe, en tête de page." },
    { "type": "text", "id": "une_heading", "label": "Titre", "default": "À la une" },
    { "type": "range", "id": "une_count", "label": "Articles à la Une en page 1 (1 principal + cartes)", "min": 1, "max": 17, "step": 1, "default": 13 },
    { "type": "header", "content": "Côté hébergeurs" },
    { "type": "checkbox", "id": "show_business", "label": "Afficher le bandeau en page 1", "default": true },
    { "type": "paragraph", "content": "Articles de l'équipe : métafield de blog custom.articles_classiques. Articles hébergeurs : custom.articles_hebergeurs. Tout article absent des deux listes va dans le fil." },
    { "type": "text", "id": "business_heading", "label": "Titre", "default": "Côté hébergeurs" },
    { "type": "text", "id": "business_intro", "label": "Introduction", "default": "Pour les propriétaires de love rooms et d'hébergements insolites." },
    { "type": "text", "id": "business_all_label", "label": "Libellé du lien « tout voir »", "default": "Tout voir" },
    { "type": "header", "content": "Toutes nos lectures" },
    { "type": "text", "id": "fil_heading", "label": "Titre", "default": "Toutes nos lectures" },
    { "type": "range", "id": "per_page", "label": "Articles par page (tous types confondus)", "min": 12, "max": 48, "step": 6, "default": 12 },
    { "type": "checkbox", "id": "show_filet", "label": "Afficher le filet (résumé)", "default": true },
    { "type": "header", "content": "Encart réservation" },
    { "type": "text", "id": "cta_heading", "label": "Titre", "default": "Passer de l'idée à la nuit" },
    { "type": "text", "id": "cta_text", "label": "Texte", "default": "Des love rooms avec jacuzzi ou spa privatif, partout en France et en Belgique." },
    { "type": "text", "id": "cta_label", "label": "Libellé du bouton", "default": "Trouver une love room" },
    { "type": "url", "id": "cta_url", "label": "Lien du bouton" }
  ],
  "blocks": [
    {
      "type": "lien",
      "name": "Lien collection",
      "settings": [
        { "type": "text", "id": "label", "label": "Libellé" },
        { "type": "url", "id": "url", "label": "Lien" }
      ]
    },
    {
      "type": "liquid",
      "name": "Liquid personnalisé",
      "settings": [
        { "type": "liquid", "id": "liquid", "label": "Code" }
      ]
    }
  ],
  "enabled_on": { "templates": ["blog"] },
  "presets": [
    { "name": "Magazine : accueil presse" }
  ]
}
{% endschema %}

