sections/main-collection.liquid:
{%- liquid
  assign show_sidebar = true
  assign total_tags = 0

  if section.settings.enable_sidebar == false or collection.filters.size == 0
    assign show_sidebar = false
  endif

  assign loven_dates_pending = false
  if request.query_parameters.start != blank and request.query_parameters.end != blank
    assign loven_dates_pending = true
  endif

  assign loven_ads_debug_on = false
  if request.query_parameters.loven_ads_debug == '1' or request.query_string contains 'loven_ads_debug=1'
    assign loven_ads_debug_on = true
  endif
-%}

{%- comment -%} loven-collection-mobile.css : déclarée dans <head> (layout/theme.liquid) pour les pages collection/recherche. {%- endcomment -%}
{%- unless request.page_type == 'collection' or request.page_type == 'search' -%}
  <link
    rel="stylesheet"
    href="{{ 'loven-collection-mobile.css' | asset_url }}"
    media="screen and (max-width: 768px)"
  >
{%- endunless -%}

<div
  id="CollectionAjaxResult"
  class="collection-content collection-content--embedded-search loven-collection-map-mobile{% if loven_dates_pending %} loven-dynamic-availability-mode{% endif %}"
  data-loven-mobile-layout="section-css-v4-dom-order"
  data-section-id="{{ section.id }}"
  data-section-type="collection-template"
  data-collection-template="true"
>
  <div class="collection-search-bar">
    {%- render 'search-bar', search_bar_embed: true, search_bar_filters_modal: false -%}
    {%- render 'loven-quick-filters', collection: collection -%}
  </div>
  {%- render 'collection-filters-modal' -%}
  <div id="CollectionAjaxContent">
    <div class="page-full">
      {%- liquid
        comment
          Grille : 24 fiches (plafond thème 48, jamais 250).
          Les marqueurs carte viennent de ?view=markers, pas de cette page.
        endcomment
        assign paginate_by = 24
        if paginate_by > 48
          assign paginate_by = 48
        endif

        assign current_filter_size = 0
        for filter in collection.filters
          assign current_filter_size = current_filter_size | plus: filter.active_values.size
        endfor
      -%}

      {%- paginate collection.products by paginate_by -%}
        {%- comment -%}
          ItemList dans le paginate : réutilise les 24 produits déjà chargés.
          Hors paginate, collection.products relance une lecture de 50 fiches et retarde le HTML.
        {%- endcomment -%}
        {%- if paginate.current_page == 1 -%}
          {%- render 'loven-collection-itemlist', collection: collection, itemlist_page: paginate.current_page -%}
        {%- endif -%}

        <div class="grid">
          <div class="grid__item medium-up--one-fifth grid__item--sidebar">
            {%- render 'collection-grid-filters',
              collection: collection,
              enable_sidebar: section.settings.enable_sidebar,
              enable_color_swatches: section.settings.enable_color_swatches,
              tags_combine: section.settings.tags_combine,
              enable_sort: section.settings.enable_sort,
              collapse_filters: section.settings.collapse_filters
            -%}
          </div>

          {%- comment -%}
            Doit être un .grid__item (comme main-search.liquid). Sinon le float + bloc sans grille
            repousse le contenu dans une bande ~20 % (colonne « sidebar ») sur mobile.
          {%- endcomment -%}
          <div class="grid__item small--one-whole grid__item--content loven-collection-main">
            <div class="collection-wrapper">
              {%- comment -%}
                Carte en premier dans le DOM : en mobile fixed, certains moteurs peignent le 2e frère
