<script>
  (function () {
    var result = document.getElementById('CollectionAjaxResult');
    if (!result || result.dataset.lovenFranceLinkBound === '1') return;
    result.dataset.lovenFranceLinkBound = '1';

    function collectLinks(node, bucket) {
      if (!node || node.nodeType !== 1) return;
      if (node.classList && node.classList.contains('lns-lien-mere')) {
        bucket.push(node);
        return;
      }
      if (!node.querySelectorAll) return;
      var found = node.querySelectorAll('.lns-lien-mere');
      for (var i = 0; i < found.length; i++) bucket.push(found[i]);
    }

    var placing = false;
    function place(rescued) {
      if (placing) return;
      var live = result.querySelector('.lns-lien-mere');
      var link = live || (rescued && rescued.length ? rescued[0] : null);
      if (!link) return;
      placing = true;
      var dynamic = result.classList.contains('loven-dynamic-availability-mode');
      var dynCount = document.getElementById('loven-dynamic-results-count');
      if (dynamic && dynCount && dynCount.parentNode) {
        if (link.parentNode !== dynCount.parentNode || link.previousElementSibling !== dynCount) {
          dynCount.insertAdjacentElement('afterend', link);
        }
      } else {
        var bar = result.querySelector('.loven-collection-results-bar');
        if (bar && link.parentElement !== bar) bar.appendChild(link);
      }
      placing = false;
      watchDynamic();
    }

    var watchedDyn = null;
    var dynObs = null;
    function watchDynamic() {
      var dyn = document.getElementById('loven-dynamic-availability');
      if (!dyn || dyn === watchedDyn) return;
      if (dynObs) dynObs.disconnect();
      watchedDyn = dyn;
      dynObs = new MutationObserver(function (records) {
        var rescued = [];
        for (var i = 0; i < records.length; i++) {
          var nodes = records[i].removedNodes;
          if (!nodes) continue;
          for (var j = 0; j < nodes.length; j++) collectLinks(nodes[j], rescued);
        }
        place(rescued);
      });
      dynObs.observe(dyn, { childList: true });
    }

    var content = document.getElementById('CollectionAjaxContent');
    if (content) {
      new MutationObserver(function () {
        watchedDyn = null;
        place();
      }).observe(content, { childList: true });
    }
    new MutationObserver(function () {
      place();
    }).observe(result, { attributes: true, attributeFilter: ['class'] });
    place();
  })();
</script>
