sections/main-gift-card.liquid:
{{ 'gift-card-page.css' | asset_url | stylesheet_tag }}

{%- liquid
  assign current_variant = product.selected_or_first_available_variant
  assign fee_percent = section.settings.fee_percent | default: 10
  assign featured_image = product.featured_image | default: product.images.first
  assign default_variant_id = current_variant.id

  for block in section.blocks
    if block.type == 'amount' and block.settings.badge != blank
      for variant in product.variants
        assign gift_cents = block.settings.gift_value | times: 100
        assign divisor = fee_percent | plus: 100.0
        assign calculated_offered = variant.price
        if fee_percent > 0 and section.settings.price_mode == 'paid'
          assign calculated_offered = variant.price | times: 100.0 | divided_by: divisor | round
        endif
        if block.settings.gift_value != blank and variant.price == gift_cents
          assign default_variant_id = variant.id
        elsif block.settings.gift_value != blank and calculated_offered == gift_cents
          assign default_variant_id = variant.id
        endif
        assign block_title = block.settings.variant_title | strip | downcase
        assign variant_title = variant.title | strip | downcase
        if block_title != blank and variant_title contains block_title
          assign default_variant_id = variant.id
        endif
      endfor
    endif
  endfor

  for variant in product.variants
    if variant.id == default_variant_id
      assign selected_variant = variant
    endif
  endfor
  if selected_variant == blank
    assign selected_variant = current_variant
  endif
-%}

{%- capture gc_money_json -%}
{
{%- for variant in product.variants -%}
  {%- liquid
    assign paid_cents = variant.price
    assign offered_cents = paid_cents
    assign fee_cents = 0
    assign amount_block = nil

    for block in section.blocks
      if block.type == 'amount'
        assign block_title = block.settings.variant_title | strip | downcase
        assign variant_title = variant.title | strip | downcase
        assign gift_cents = block.settings.gift_value | times: 100
        assign divisor = fee_percent | plus: 100.0
        assign calculated_offered = variant.price
        if fee_percent > 0 and section.settings.price_mode == 'paid'
          assign calculated_offered = variant.price | times: 100.0 | divided_by: divisor | round
        endif
        if block.settings.gift_value != blank and variant.price == gift_cents
          assign amount_block = block
        elsif block.settings.gift_value != blank and calculated_offered == gift_cents
          assign amount_block = block
        elsif block_title != blank and variant_title contains block_title
          assign amount_block = block
        endif
      endif
    endfor

    if amount_block and amount_block.settings.gift_value != blank
      assign offered_cents = amount_block.settings.gift_value | times: 100
    elsif fee_percent > 0
      if section.settings.price_mode == 'paid'
        assign divisor = fee_percent | plus: 100.0
        assign offered_cents = paid_cents | times: 100.0 | divided_by: divisor | round
      else
        assign offered_cents = paid_cents
        assign paid_cents = paid_cents | times: fee_percent | plus: 100.0 | divided_by: 100.0 | round
      endif
    endif
    assign fee_cents = paid_cents | minus: offered_cents
    if fee_cents < 0
      assign fee_cents = 0
    endif
  -%}
  "{{ variant.id }}": {
    "id": {{ variant.id }},
    "available": {{ variant.available | json }},
    "paid": {{ paid_cents }},
    "offered": {{ offered_cents }},
    "fee": {{ fee_cents }},
    "paid_formatted": {{ paid_cents | money_without_trailing_zeros | json }},
    "offered_formatted": {{ offered_cents | money_without_trailing_zeros | json }},
    "fee_formatted": {{ fee_cents | money_without_trailing_zeros | json }},
    "image": {% if variant.featured_image %}{{ variant.featured_image | img_url: '1000x' | json }}{% else %}null{% endif %}
  }{% unless forloop.last %},{% endunless %}
{%- endfor -%}
}
{%- endcapture -%}

{%- liquid
  assign selected_paid = selected_variant.price
  assign selected_offered = selected_paid
  assign selected_fee = 0
  for block in section.blocks
    if block.type == 'amount'
      assign block_title = block.settings.variant_title | strip | downcase
      assign variant_title = selected_variant.title | strip | downcase
      assign gift_cents = block.settings.gift_value | times: 100
      if block.settings.gift_value != blank and selected_variant.price == gift_cents
        assign selected_offered = gift_cents
      elsif block_title != blank and variant_title contains block_title and block.settings.gift_value != blank
        assign selected_offered = gift_cents
      endif
    endif
  endfor
  if selected_offered == selected_paid and fee_percent > 0
    if section.settings.price_mode == 'paid'
      assign divisor = fee_percent | plus: 100.0
      assign selected_offered = selected_paid | times: 100.0 | divided_by: divisor | round
    endif
  endif
  assign selected_fee = selected_paid | minus: selected_offered
  if selected_fee < 0
    assign selected_fee = 0
  endif
-%}

<div
  id="gift-card-hero"
  class="gc gc-hero"
  data-gift-card-hero
  data-fee-percent="{{ fee_percent }}"
>
  <script type="application/json" data-gift-variants>{{ gc_money_json }}</script>
  <div class="gc-wrap">
    <div class="gc-hero__grid">
      <div class="gc-hero__gallery gc-gallery">
        {%- if section.settings.badge_text != blank -%}
          <div class="gc-badge">
            <img
              class="gc-icon"
              src="{{ 'gc-icon-email.svg' | asset_url }}"
              alt=""
              width="16"
              height="16"
            >
            <span>{{ section.settings.badge_text | escape }}</span>
          </div>
        {%- endif -%}

        <div class="gc-gallery__main">
          {%- if featured_image != blank -%}
            <img
              data-gc-main-image
              src="{{ featured_image | img_url: '1000x' }}"
              alt="{{ featured_image.alt | default: product.title | escape }}"
              width="1000"
              height="1000"
            >
          {%- else -%}
            {{ 'image' | placeholder_svg_tag: 'placeholder-svg' }}
          {%- endif -%}
        </div>

        {%- if product.images.size > 1 -%}
          <div class="gc-thumbs" data-gc-thumbs>
            {%- for image in product.images -%}
              <button
                type="button"
                class="gc-thumbs__btn{% if image == featured_image %} is-active{% endif %}"
                data-gc-thumb
                data-src="{{ image | img_url: '1000x' }}"
                aria-label="{{ image.alt | default: product.title | escape }}"
              >
                <img
                  src="{{ image | img_url: '200x' }}"
                  alt="{{ image.alt | default: product.title | escape }}"
                  width="200"
                  height="200"
                >
              </button>
            {%- endfor -%}
          </div>
        {%- endif -%}
      </div>

      <div class="gc-hero__buy gc-buy">
        {%- if section.settings.eyebrow != blank -%}
          <p class="gc-eyebrow">{{ section.settings.eyebrow | escape }}</p>
        {%- endif -%}

        {%- if section.settings.title != blank -%}
          <h1 class="gc-buy__title">{{ section.settings.title | escape }}</h1>
        {%- else -%}
          <h1 class="gc-buy__title">{{ product.title | escape }}</h1>
        {%- endif -%}

        {%- if section.settings.highlight_1 != blank or section.settings.highlight_2 != blank -%}
          <div class="gc-highlights">
            {%- if section.settings.highlight_1 != blank -%}
              <div class="gc-highlight">
                <img class="gc-icon" src="{{ 'gc-icon-pin.svg' | asset_url }}" alt="" width="16" height="16">
                <span>{{ section.settings.highlight_1 | escape }}</span>
              </div>
            {%- endif -%}
            {%- if section.settings.highlight_2 != blank -%}
              <div class="gc-highlight">
                <img class="gc-icon" src="{{ 'gc-icon-calendar.svg' | asset_url }}" alt="" width="16" height="16">
                <span>{{ section.settings.highlight_2 | escape }}</span>
              </div>
            {%- endif -%}
          </div>
        {%- endif -%}

        {% form 'product', product, class: 'gc-form', id: 'GiftCardProductForm' %}
          <input type="hidden" name="id" value="{{ selected_variant.id }}" data-gc-variant-input>

          <div class="gc-card">
            <div class="gc-card__body">
              <div class="gc-card__label">
                {%- if section.settings.amounts_label != blank -%}
                  <p class="gc-card__label-text">{{ section.settings.amounts_label | escape }}</p>
                {%- endif -%}
                <span class="gc-rule"></span>
              </div>

              <div class="gc-amounts" role="radiogroup" aria-label="{{ section.settings.amounts_label | escape }}">
                {%- for variant in product.variants -%}
                  {%- liquid
                    assign amount_desc = ''
                    assign amount_badge = ''
                    assign amount_block = nil
                    assign display_price = variant.price
                    for block in section.blocks
                      if block.type == 'amount'
                        assign block_title = block.settings.variant_title | strip | downcase
                        assign variant_title = variant.title | strip | downcase
                        assign gift_cents = block.settings.gift_value | times: 100
                        assign matched = false
                        assign calculated_offered = variant.price
                        if fee_percent > 0 and section.settings.price_mode == 'paid'
                          assign divisor = fee_percent | plus: 100.0
                          assign calculated_offered = variant.price | times: 100.0 | divided_by: divisor | round
                        endif
                        if block.settings.gift_value != blank and variant.price == gift_cents
                          assign matched = true
                        elsif block.settings.gift_value != blank and calculated_offered == gift_cents
                          assign matched = true
                        elsif block_title != blank and variant_title contains block_title
                          assign matched = true
                        endif
                        if matched
                          assign amount_block = block
                          assign amount_desc = block.settings.description
                          assign amount_badge = block.settings.badge
                          if block.settings.gift_value != blank
                            assign display_price = gift_cents
                          endif
                        endif
                      endif
                    endfor
                    if amount_block == nil and fee_percent > 0 and section.settings.price_mode == 'paid'
                      assign divisor = fee_percent | plus: 100.0
                      assign display_price = variant.price | times: 100.0 | divided_by: divisor | round
                    endif
                  -%}
                  <button
                    type="button"
                    class="gc-amount{% if variant.id == selected_variant.id %} is-selected{% endif %}"
                    role="radio"
                    aria-checked="{% if variant.id == selected_variant.id %}true{% else %}false{% endif %}"
                    data-gc-amount
                    data-variant-id="{{ variant.id }}"
                    {% if amount_block %}{{ amount_block.shopify_attributes }}{% endif %}
                  >
                    {%- if amount_badge != blank -%}
                      <span class="gc-amount__badge">{{ amount_badge | escape }}</span>
                    {%- endif -%}
                    <span class="gc-amount__price">{{ display_price | money_without_trailing_zeros }}</span>
                    {%- if amount_desc != blank -%}
                      <span class="gc-amount__desc">{{ amount_desc | escape }}</span>
                    {%- endif -%}
                  </button>
                {%- endfor -%}
              </div>

              <div class="gc-summary">
                <div class="gc-summary__row">
                  <span>{{ section.settings.value_label | escape }}</span>
                  <span data-gc-offered>{{ selected_offered | money_without_trailing_zeros }}</span>
                </div>
                {%- if fee_percent > 0 -%}
                  <div class="gc-summary__row">
                    <span>{{ section.settings.fee_label | escape }}</span>
                    <span data-gc-fee>{{ selected_fee | money_without_trailing_zeros }}</span>
                  </div>
                {%- endif -%}
                <div class="gc-summary__total">
                  <span class="gc-summary__total-label">{{ section.settings.total_label | escape }}</span>
                  <span class="gc-summary__total-value" data-gc-paid>{{ selected_paid | money_without_trailing_zeros }}</span>
                </div>
                <button
                  type="submit"
                  name="add"
                  class="gc-btn gc-btn--full gc-card__cta add-to-cart"
                  {% unless selected_variant.available %}disabled{% endunless %}
                  data-gc-submit
                  data-add-to-cart
                >
                  {{ section.settings.button_label | escape }}
                </button>
              </div>

              {%- if section.settings.fine_print != blank -%}
                <p class="gc-fine">{{ section.settings.fine_print | escape }}</p>
              {%- endif -%}
            </div>

            {%- assign has_perks = false -%}
            {%- for block in section.blocks -%}
              {%- if block.type == 'perk' -%}
                {%- assign has_perks = true -%}
              {%- endif -%}
            {%- endfor -%}
            {%- if has_perks -%}
              <div class="gc-perks">
                {%- for block in section.blocks -%}
                  {%- if block.type == 'perk' -%}
                    {%- liquid
                      assign perk_icon = 'gc-icon-send.svg'
                      case block.settings.icon
                        when 'validity'
                          assign perk_icon = 'gc-icon-validity.svg'
                        when 'lock'
                          assign perk_icon = 'gc-icon-lock.svg'
                        when 'map'
                          assign perk_icon = 'gc-icon-map.svg'
                        when 'email'
                          assign perk_icon = 'gc-icon-send.svg'
                      endcase
                    -%}
                    <div class="gc-perk" {{ block.shopify_attributes }}>
                      <div class="gc-perk__icon">
                        <img class="gc-icon" src="{{ perk_icon | asset_url }}" alt="" width="16" height="16">
                      </div>
                      <div>
                        {%- if block.settings.title != blank -%}
                          <p class="gc-perk__title">{{ block.settings.title | escape }}</p>
                        {%- endif -%}
                        {%- if block.settings.text != blank -%}
                          <p class="gc-perk__text">{{ block.settings.text | escape }}</p>
                        {%- endif -%}
                      </div>
                    </div>
                  {%- endif -%}
                {%- endfor -%}
              </div>
            {%- endif -%}
          </div>
        {% endform %}

        {%- if section.settings.legal != blank -%}
          <p class="gc-legal">{{ section.settings.legal | escape }}</p>
        {%- endif -%}
      </div>
    </div>
  </div>
</div>

{%- if section.settings.show_sticky -%}
  <div class="gc gc-sticky" data-gc-sticky>
    <div>
      <div class="gc-sticky__price" data-gc-sticky-paid>{{ selected_paid | money_without_trailing_zeros }}</div>
      <p class="gc-sticky__offered">
        <span data-gc-sticky-offered>{{ selected_offered | money_without_trailing_zeros }}</span>
        {{ section.settings.sticky_offered_suffix | escape }}
      </p>
    </div>
    <button type="button" class="gc-btn gc-btn--sticky" data-gc-sticky-submit>
      {{ section.settings.sticky_button_label | escape }}
    </button>
  </div>
{%- endif -%}

<script>
  (function () {
    var root = document.querySelector('[data-gift-card-hero]');
    if (!root) return;
    var jsonEl = root.querySelector('[data-gift-variants]');
    var map = {};
    try { map = JSON.parse(jsonEl.textContent); } catch (e) {}
    var input = root.querySelector('[data-gc-variant-input]');
    var form = document.getElementById('GiftCardProductForm');
    var offeredEl = root.querySelector('[data-gc-offered]');
    var feeEl = root.querySelector('[data-gc-fee]');
    var paidEl = root.querySelector('[data-gc-paid]');
    var mainImg = root.querySelector('[data-gc-main-image]');
    var stickyPaid = document.querySelector('[data-gc-sticky-paid]');
    var stickyOffered = document.querySelector('[data-gc-sticky-offered]');
    var amounts = root.querySelectorAll('[data-gc-amount]');

    function selectVariant(id) {
      var data = map[id];
      if (!data || !input) return;
      input.value = id;
      amounts.forEach(function (btn) {
        var on = btn.getAttribute('data-variant-id') === String(id);
        btn.classList.toggle('is-selected', on);
        btn.setAttribute('aria-checked', on ? 'true' : 'false');
      });
      if (offeredEl) offeredEl.textContent = data.offered_formatted;
      if (feeEl) feeEl.textContent = data.fee_formatted;
      if (paidEl) paidEl.textContent = data.paid_formatted;
      if (stickyPaid) stickyPaid.textContent = data.paid_formatted;
      if (stickyOffered) stickyOffered.textContent = data.offered_formatted;
      if (data.image && mainImg) mainImg.src = data.image;
    }

    amounts.forEach(function (btn) {
      btn.addEventListener('click', function () {
        selectVariant(btn.getAttribute('data-variant-id'));
      });
    });

    root.querySelectorAll('[data-gc-thumb]').forEach(function (btn) {
      btn.addEventListener('click', function () {
        root.querySelectorAll('[data-gc-thumb]').forEach(function (el) {
          el.classList.remove('is-active');
        });
        btn.classList.add('is-active');
        if (mainImg) mainImg.src = btn.getAttribute('data-src');
      });
    });

    function submitForm() {
      if (form) form.requestSubmit ? form.requestSubmit() : form.submit();
    }
    var stickySubmit = document.querySelector('[data-gc-sticky-submit]');
    if (stickySubmit) {
      stickySubmit.addEventListener('click', function () {
        submitForm();
      });
    }
    if (form && window.theme && theme.AjaxProduct) {
      new theme.AjaxProduct(form, '[data-gc-submit]');
    }
  })();
</script>

