sections/main-search.liquid:
{%- comment -%}
  Aligné sur main-collection : barre Love'n Spa, carte + grille, pagination.
  Corrigé : paginate_by défini, plus de block.shopify_attributes invalide.
{%- endcomment -%}
{%- liquid
  assign loven_dates_pending = false
  if request.query_parameters.start != blank and request.query_parameters.end != blank
    if search.performed and search.results_count > 0
      assign loven_dates_pending = true
    endif
  endif
  assign loven_ads_debug_on = false
  if request.query_parameters.loven_ads_debug == '1' or request.query_string contains 'loven_ads_debug=1'
    assign loven_ads_debug_on = true
  endif
-%}
{%- comment -%} loven-collection-mobile.css : déclarée dans <head> (layout/theme.liquid) pour les pages collection/recherche. {%- endcomment -%}
{%- unless request.page_type == 'collection' or request.page_type == 'search' -%}
  <link
    rel="stylesheet"
    href="{{ 'loven-collection-mobile.css' | asset_url }}"
    media="screen and (max-width: 768px)"
  >
{%- endunless -%}

<div
  id="CollectionAjaxResult"
  class="collection-content collection-content--embedded-search loven-collection-map-mobile{% if loven_dates_pending %} loven-dynamic-availability-mode{% endif %}"
  data-loven-mobile-layout="section-css-v4-dom-order"
  data-section-id="{{ section.id }}"
  data-section-type="collection-template"
  data-collection-template="true"
>
{%- comment -%}
  15/10/2026 : « search-template » n'était enregistré nulle part dans theme.js, donc theme.Collection
  n'était jamais créé sur /search et cocher un filtre du panneau ne faisait rien. Même type que main-collection.
  Test : tests/e2e/loven-filters-recherche.e2e.mjs
{%- endcomment -%}
  <div class="collection-search-bar">
    {%- render 'search-bar', search_bar_embed: true, search_bar_filters_modal: false -%}
    {%- render 'loven-quick-filters', collection: search -%}
  </div>
  {%- render 'collection-filters-modal' -%}

  <div id="CollectionAjaxContent">
    <div class="page-full">
      {%- liquid
        comment
          Grille : 24 fiches (plafond thème 48). Marqueurs : ?view=markers.
        endcomment
        assign paginate_by = 24
        if paginate_by > 48
          assign paginate_by = 48
        endif
        assign current_filter_size = 0
        for filter in search.filters
          assign current_filter_size = current_filter_size | plus: filter.active_values.size
        endfor
      -%}

      {%- if search.performed -%}
        {%- if search.results_count == 0 -%}
          <div class="section-header">
            <p>{{ 'general.search.no_results_html' | t: terms: search.terms | replace: '*', '' }}</p>
          </div>
        {%- else -%}
          {%- paginate search.results by paginate_by -%}
            <div class="grid">
              <div class="grid__item medium-up--one-fifth grid__item--sidebar">
                {%-
                  render 'collection-grid-filters',
                  collection: search,
                  enable_sidebar: section.settings.enable_sidebar,
                  enable_color_swatches: section.settings.enable_color_swatches,
                  tags_combine: section.settings.tags_combine,
                  enable_sort: section.settings.enable_sort,
                  collapse_filters: section.settings.collapse_filters
                -%}
              </div>

              <div class="grid__item small--one-whole grid__item--content loven-collection-main">
                <div class="collection-wrapper">
                  <div class="map-container">
                    {%- render 'search-map' -%}
                  </div>
                  <div class="rooms-container" id="loven-rooms-sheet-root">
                    {%- render 'loven-rooms-sheet-chrome' -%}
                    {%- render 'loven-collection-active-filters', collection: search -%}
                    <div class="loven-rooms-sheet-body" id="loven-rooms-sheet-body">
                    <div
                      id="loven-dynamic-availability"
                      class="loven-dynamic-availability"
                      {% unless loven_dates_pending %}
                        hidden
                      {% endunless %}
                      {% if loven_dates_pending %}
                        data-loven-skeleton-initial="1"
                      {% endif %}
                    >
                      {%- if loven_dates_pending -%}
                        {%- render 'loven-collection-grid-skeleton' -%}
                      {%- endif -%}
                    </div>
                    <div class="loven-static-collection-grid">
                      {%- render 'collection-grid',
                        collection: search,
                        items: search.results,
                        grid_style: 'large',
                        quick_shop_enable: settings.quick_shop_enable,
                        map_mobile_sheet: true,
                        defer_grid_images: loven_dates_pending,
                        grid_page: paginate.current_page
                      -%}
                      {%- if paginate.pages > 1 -%}
                        <div class="loven-collection-pagination">
                          {%- render 'pagination', paginate: paginate -%}
                        </div>
                      {%- endif -%}
                    </div>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          {%- endpaginate -%}
        {%- endif -%}
      {%- else -%}
        <header class="section-header">
          <h1 class="section-header__title">{{ 'general.search.title' | t }}</h1>
          <p class="medium-up--hide">{{ 'general.search.placeholder' | t }}</p>
        </header>
      {%- endif -%}
    </div>
  </div>
</div>

{%- style -%}
