      align-self: flex-start;
      position: sticky;
      top: var(--loven-map-sticky-top, 108px);
      z-index: 0;
      margin-top: 0;
      padding-top: 0;
      overflow: visible !important;
    }
    .collection-content .map-container #map {
      position: relative;
      top: auto;
      width: 100%;
      min-height: 400px;
      height: calc(100vh - var(--loven-map-sticky-top, 108px) - 8px);
      max-height: calc(100vh - var(--loven-map-sticky-top, 108px) - 8px);
      margin-top: 0;
    }
  }
  @media only screen and (min-width: 769px) {
    .collection-content--embedded-search .grid__item--sidebar {
      display: none !important;
    }
    .collection-content--embedded-search .collection-wrapper {
      width: 100%;
    }
    .collection-content--embedded-search .rooms-container {
      order: 1;
      flex: 1 1 100%;
      max-width: 49%;
    }
    .collection-content .rooms-container .collection-grid[data-view='large'] .grid-item {
      flex: 0 0 33.33333%;
      max-width: 33.33333%;
    }
  }
  #CollectionSidebar .tag-list--active-tags .tag--remove {
    display: block;
    margin: 0 0 10px;
  }
  #CollectionSidebar .tag-list--active-tags .tag--remove a.btn {
    background: transparent !important;
    border: 0 !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    color: var(--colorTextBody, #1c1d1d) !important;
    font-weight: 400;
    min-width: 0;
    min-height: 44px;
    display: flex;
    align-items: center;
    padding: 8px 12px 8px 36px !important;
    text-align: left;
    text-decoration: underline;
    text-underline-offset: 2px;
  }
  #CollectionSidebar .tag-list--active-tags .tag--remove a.btn:hover {
    background: transparent !important;
    color: var(--colorTextBody, #1c1d1d) !important;
  }
  #CollectionSidebar .filter-form .tag:not(.tag--swatch) {
    display: block;
    margin: 0 0 6px;
  }
  #CollectionSidebar .filter-form .tag:not(.tag--swatch) label.tag__checkbox-wrapper {
    padding: 4px 0;
    border: 0;
    border-radius: 0;
    background: transparent;
  }
{%- endstyle -%}

<script src="{{ 'loven-collection-mobile.js' | asset_url }}" defer="defer"></script>

{% schema %}
