              <div class="password-form-group">
                <input type="email" value="{% if customer %}{{ customer.email }}{% endif %}" placeholder="{{ section.settings.newsletter_placeholder }}" name="contact[email]" id="Email-{{ section.id }}" class="password-form-group__input" autocapitalize="off">
                <button type="submit" class="password-form-group__submit" name="commit" title="{{ 'general.newsletter_form.submit' | t }}">
