        },
        {
          "type": "header",
          "content": "t:sections.promo-grid.blocks.hero.settings.header_layout"
        },
        {
          "type": "select",
          "id": "width",
          "label": "t:sections.promo-grid.blocks.hero.settings.width.label",
          "default": "100",
          "options": [
