sections/seo-long-form.liquid:
{%- liquid
  assign loven_hide_collection_extra = false
  if request.page_type == 'collection' and current_page > 1
    assign loven_hide_collection_extra = true
  endif
-%}
{%- unless loven_hide_collection_extra -%}
{% if collection.description != blank %}
  <div class="index-section seo-long-form">
    <div class="seo-long-form__content page-width">
      <div class="seo-long-form__columns">
        {%- comment -%}
          Images de la description (admin, pleine taille, ex. 387 Ko) : bloc sous la ligne de
          flottaison, donc lazy + decoding async pour ne pas concurrencer cartes et tuiles carte.
        {%- endcomment -%}
        {{ collection.description | replace: '<img ', '<img loading="lazy" decoding="async" ' }}
      </div>
    </div>
  </div>
{% endif %}
{%- endunless -%}

{% style %}
  /* Bloc éditorial des collections : lecture pleine largeur, une colonne de 68 ch.
     14/10/2026 : suppression de la boîte de 400 px à défilement interne et des 3 colonnes CSS
     (25 % du texte visible, ordre de lecture cassé, 47 liens indiscernables du texte). */
  .seo-long-form{background:#FBF6F2;padding:24px 16px}
  .seo-long-form__content{
    padding:32px 20px;background:#FFF;border-radius:12px;
    color:#222;font-size:1rem;line-height:1.6;text-align:left
  }
  /* La largeur de lecture est posée sur __columns : .page-width est forcé à 1800 px sur les collections */
  .seo-long-form__columns{max-width:1100px;margin:0 auto;column-count:auto}
  .seo-long-form__content > section{margin-top:2.5rem}
  .seo-long-form__content > section:first-child{margin-top:0}
  .seo-long-form__content h2,
  .seo-long-form__content h3,
  .seo-long-form__content p,
  .seo-long-form__content ol{max-width:68ch}
  .seo-long-form__content h2{font-size:1.5rem;line-height:1.25;font-weight:700;margin:2.5rem 0 .75rem}
  .seo-long-form__content section > h2:first-child{margin-top:0}
  .seo-long-form__content h3{font-size:1.125rem;line-height:1.35;font-weight:700;margin:1.75rem 0 .5rem}
  .seo-long-form__content p{margin:0 0 1rem}
  .seo-long-form__content ul,.seo-long-form__content ol{margin:0 0 1rem;padding-left:1.25rem}
  .seo-long-form__content li{margin:0 0 .4rem}
  .seo-long-form__content strong{font-weight:700}

  /* Liens de prose : visibles, rose en accent, soulignement décalé */
  .seo-long-form__content a{
    color:#E83F4E;text-decoration:underline;text-decoration-thickness:1px;text-underline-offset:2px
  }
  .seo-long-form__content a:hover{text-decoration-thickness:2px}
  .seo-long-form__content a:focus-visible{outline:2px solid #E83F4E;outline-offset:2px;border-radius:2px}

  /* Listes de navigation géo (régions, villes) : grille de pastilles, cible tactile de 44 px */
  .seo-long-form__content .love-room-regions ul{
    list-style:none;padding:0;margin:0 0 1.5rem;max-width:none;
    display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:8px 12px
  }
  .seo-long-form__content .love-room-regions li{margin:0}
  .seo-long-form__content .love-room-regions li a{
    display:flex;align-items:center;min-height:44px;padding:10px 14px;
    background:#FBF6F2;border-radius:8px;color:#222;text-decoration:none;font-weight:400
  }
  .seo-long-form__content .love-room-regions li a:hover{color:#E83F4E;background:#F7ECE4}

  /* FAQ : questions détachées, réponses alignées */
  .seo-long-form__content .faq-item{padding:1rem 0;border-top:1px solid #EFE6DF}
  .seo-long-form__content .faq-item:last-child{border-bottom:1px solid #EFE6DF}
  .seo-long-form__content .faq-item h3{margin:0 0 .5rem}
  .seo-long-form__content .faq-item p{margin:0}

  @media screen and (min-width:768px){
    .seo-long-form{padding:48px 40px}
    .seo-long-form__content{padding:56px 64px}
  }
{% endstyle %}

{% schema %}
{
  "name": "SEO long form",
  "presets":[
    {
      "name":"SEO long form"
    }
  ]
}
{% endschema %}

sections/slideshow-image.liquid:
{%- unless section.settings.full_width -%}
  <div class="page-width hero--padded">
{%- endunless -%}
<div
  data-section-id="{{ section.id }}"
  data-section-type="slideshow-section"
  {% if section.blocks.size == 1 %}data-immediate-load{% endif %}
>
  {%- if section.blocks.size > 0 -%}
    <div class="slideshow-wrapper">
      {%- if section.settings.autoplay and section.settings.style == 'bars' and section.blocks.size > 1 -%}
        {%- style -%}
          [data-bars][data-autoplay="true"] .flickity-page-dots .dot:after {
            animation-duration: {{ section.settings.autoplay_speed | times: 1000 }}ms;
          }
        {%- endstyle -%}

        <button type="button" class="visually-hidden slideshow__pause" data-id="{{ section.id }}" aria-live="polite">
          <span class="slideshow__pause-stop">
            <svg aria-hidden="true" focusable="false" role="presentation" class="icon icon-pause" viewBox="0 0 10 13">
              <g fill="#000" fill-rule="evenodd"><path d="M0 0h3v13H0zM7 0h3v13H7z"/></g>
            </svg>
            <span class="icon__fallback-text">{{ 'sections.slideshow.pause_slideshow' | t }}</span>
          </span>
          <span class="slideshow__pause-play">
            <svg
              aria-hidden="true"
              focusable="false"
              role="presentation"
              class="icon icon-play"
              viewBox="18.24 17.35 24.52 28.3"
            >
              <path fill="#323232" d="M22.1 19.151v25.5l20.4-13.489-20.4-12.011z"/>
            </svg>
            <span class="icon__fallback-text">{{ 'sections.slideshow.play_slideshow' | t }}</span>
          </span>
        </button>
      {%- endif -%}

      {%- assign natural_height_ratio = '60%' -%}
      {%- assign natural_height_ratio_mobile = '100%' -%}
      {%- for block in section.blocks limit: 1 -%}
        {%- if block.settings.image != blank -%}
          {%- capture natural_height_ratio -%}{{ 100 | divided_by: block.settings.image.aspect_ratio }}%{% endcapture %}
          {%- assign natural_height_ratio_mobile = natural_height_ratio -%}
        {%- endif -%}
        {%- if block.settings.image_mobile != blank -%}
          {%- capture natural_height_ratio_mobile -%}{{ 100 | divided_by: block.settings.image_mobile.aspect_ratio }}%{% endcapture %}
        {%- endif -%}
      {%- endfor -%}

      {%- style -%}
        .hero-natural--{{ section.id }} {
          height: 0;
          padding-bottom: {{ natural_height_ratio }};
        }

        @media screen and (max-width: 768px) {
          .hero-natural--{{ section.id }} {
            padding-bottom: {{ natural_height_ratio_mobile }};
          }
        }
      {%- endstyle -%}

      <div class="hero-natural--{{ section.id }}">
        <div
          id="Slideshow-{{ section.id }}"
          class="hero hero--{{ section.id }} loading"
          data-natural="true"
          data-autoplay="{{ section.settings.autoplay }}"
          data-speed="{{ section.settings.autoplay_speed | times: 1000 }}"
          {% if section.settings.style == 'arrows' %}
            data-arrows="true"
          {% endif %}
          {% if section.settings.style == 'dots' %}
            data-dots="true"
          {% endif %}
          {% if section.settings.style == 'bars' %}
            data-dots="true"
            data-bars="true"
          {% endif %}
          data-slide-count="{{ section.blocks.size }}"
        >
          {%- for block in section.blocks -%}
            <div
              {{ block.shopify_attributes }}
              class="slideshow__slide slideshow__slide--{{ block.id }}"
              data-index="{{ forloop.index0 }}"
              data-id="{{ block.id }}"
            >
              {%- liquid
                assign has_mobile_image = false
                if block.settings.image_mobile != blank
                  assign has_mobile_image = true
                endif
              -%}

              <div class="hero__image-wrapper">
                {%- if block.settings.image != blank -%}
                  {%- if forloop.first -%}
                    {%- if has_mobile_image -%}
                      <picture class="hero__picture">
                        <source
                          media="(max-width: 768px)"
                          srcset="
                            {{ block.settings.image_mobile | image_url: width: 375 }} 375w,
                            {{ block.settings.image_mobile | image_url: width: 550 }} 550w,
                            {{ block.settings.image_mobile | image_url: width: 750 }} 750w,
                            {{ block.settings.image_mobile | image_url: width: 1100 }} 1100w,
                            {{ block.settings.image_mobile | image_url: width: 1500 }} 1500w
                          "
                          sizes="100vw"
                        >
                        <img
                          class="hero__image hero__image--{{ block.id }} hero__image--instant"
                          src="{{ block.settings.image | image_url: width: 1200 }}"
                          srcset="
                            {{ block.settings.image | image_url: width: 375 }} 375w,
                            {{ block.settings.image | image_url: width: 550 }} 550w,
                            {{ block.settings.image | image_url: width: 750 }} 750w,
                            {{ block.settings.image | image_url: width: 1100 }} 1100w,
                            {{ block.settings.image | image_url: width: 1500 }} 1500w,
                            {{ block.settings.image | image_url: width: 1920 }} 1920w,
                            {{ block.settings.image | image_url: width: 2560 }} 2560w,
                            {{ block.settings.image | image_url: width: 3840 }} 3840w
                          "
                          sizes="100vw"
                          width="{{ block.settings.image.width }}"
                          height="{{ block.settings.image.height }}"
                          loading="eager"
                          fetchpriority="high"
                          decoding="async"
                          alt="{{ block.settings.image.alt | escape }}"
                        >
                      </picture>
                    {%- else -%}
                      <img
                        class="hero__image hero__image--{{ block.id }} hero__image--instant"
                        src="{{ block.settings.image | image_url: width: 1200 }}"
                        srcset="
                          {{ block.settings.image | image_url: width: 375 }} 375w,
                          {{ block.settings.image | image_url: width: 550 }} 550w,
                          {{ block.settings.image | image_url: width: 750 }} 750w,
                          {{ block.settings.image | image_url: width: 1100 }} 1100w,
                          {{ block.settings.image | image_url: width: 1500 }} 1500w,
                          {{ block.settings.image | image_url: width: 1920 }} 1920w,
                          {{ block.settings.image | image_url: width: 2560 }} 2560w,
                          {{ block.settings.image | image_url: width: 3840 }} 3840w
                        "
                        sizes="100vw"
                        width="{{ block.settings.image.width }}"
                        height="{{ block.settings.image.height }}"
                        loading="eager"
                        fetchpriority="high"
                        decoding="async"
                        alt="{{ block.settings.image.alt | escape }}"
                      >
                    {%- endif -%}
                  {%- else -%}
                    {%- assign img_url = block.settings.image | img_url: '1x1' | replace: '_1x1.', '_{width}x.' -%}
                    <img
                      class="hero__image hero__image--{{ block.id }} lazyload{% if has_mobile_image %} small--hide{% endif %}"
                      src="{{ block.settings.image | img_url: '300x' }}"
                      data-src="{{ img_url }}"
                      data-aspectratio="{{ block.settings.image.aspect_ratio }}"
                      data-sizes="auto"
                      alt="{{ block.settings.image.alt | escape }}"
                    >
                    {%- if has_mobile_image -%}
                      {%- assign img_url_mobile = block.settings.image_mobile
                        | img_url: '1x1'
                        | replace: '_1x1.', '_{width}x.'
                      -%}
                      <img
                        class="hero__image hero__image--{{ block.id }} lazyload medium-up--hide"
                        src="{{ block.settings.image_mobile | img_url: '300x' }}"
                        data-src="{{ img_url_mobile }}"
                        data-aspectratio="{{ block.settings.image_mobile.aspect_ratio }}"
                        data-sizes="auto"
                        alt="{{ block.settings.image_mobile.alt | escape }}"
                      >
                    {%- endif -%}
                  {%- endif -%}
                  <noscript>
                    <img
                      class="hero__image hero__image--{{ block.id }}"
                      src="{{ block.settings.image | img_url: '1400x' }}"
                      alt="{{ block.settings.image.alt | escape }}"
