                    content: '';
                    position: absolute;
                    left: 0;
                    right: 0;
                    top: 0;
                    bottom: 0;
                    z-index: 3;
                    background-color: #000;
                    opacity: {{ block.settings.overlay_opacity | divided_by: 100.0 }};
                  }
                {% endif %}
              {%- endstyle -%}

              {%- liquid
                assign hero_text = false
                if block.settings.top_subheading != blank or block.settings.title != blank or block.settings.subheading != blank or block.settings.link_text != blank
                  assign hero_text = true
                endif

                assign has_mobile_image = false
                if block.settings.image_mobile != blank
                  assign has_mobile_image = true
                endif
              -%}

              <div class="hero__image-wrapper{% unless hero_text %} hero__image-wrapper--no-overlay{% endunless %}">
                {%- if block.settings.image != blank -%}
                  {%- if forloop.first -%}
                    {%- if has_mobile_image -%}
                      <picture class="hero__picture">
                        <source
                          media="(max-width: 768px)"
                          srcset="
                            {{ block.settings.image_mobile | image_url: width: 375 }} 375w,
                            {{ block.settings.image_mobile | image_url: width: 550 }} 550w,
                            {{ block.settings.image_mobile | image_url: width: 750 }} 750w,
                            {{ block.settings.image_mobile | image_url: width: 1100 }} 1100w,
                            {{ block.settings.image_mobile | image_url: width: 1500 }} 1500w
                          "
                          sizes="100vw"
                        >
                        <img
                          class="hero__image hero__image--{{ block.id }} hero__image--instant"
                          src="{{ block.settings.image | image_url: width: 1200 }}"
                          srcset="
                            {{ block.settings.image | image_url: width: 375 }} 375w,
                            {{ block.settings.image | image_url: width: 550 }} 550w,
                            {{ block.settings.image | image_url: width: 750 }} 750w,
                            {{ block.settings.image | image_url: width: 1100 }} 1100w,
                            {{ block.settings.image | image_url: width: 1500 }} 1500w,
                            {{ block.settings.image | image_url: width: 1920 }} 1920w,
                            {{ block.settings.image | image_url: width: 2560 }} 2560w,
                            {{ block.settings.image | image_url: width: 3840 }} 3840w
                          "
                          sizes="100vw"
                          width="{{ block.settings.image.width }}"
                          height="{{ block.settings.image.height }}"
                          loading="eager"
                          fetchpriority="high"
                          decoding="async"
                          alt="{{ block.settings.image.alt | escape }}"
                          style="object-position: {{ block.settings.focal_point }}"
                        >
                      </picture>
                    {%- else -%}
                      <img
                        class="hero__image hero__image--{{ block.id }} hero__image--instant"
                        src="{{ block.settings.image | image_url: width: 1200 }}"
                        srcset="
                          {{ block.settings.image | image_url: width: 375 }} 375w,
                          {{ block.settings.image | image_url: width: 550 }} 550w,
                          {{ block.settings.image | image_url: width: 750 }} 750w,
                          {{ block.settings.image | image_url: width: 1100 }} 1100w,
                          {{ block.settings.image | image_url: width: 1500 }} 1500w,
                          {{ block.settings.image | image_url: width: 1920 }} 1920w,
                          {{ block.settings.image | image_url: width: 2560 }} 2560w,
                          {{ block.settings.image | image_url: width: 3840 }} 3840w
                        "
                        sizes="100vw"
                        width="{{ block.settings.image.width }}"
                        height="{{ block.settings.image.height }}"
                        loading="eager"
                        fetchpriority="high"
                        decoding="async"
                        alt="{{ block.settings.image.alt | escape }}"
                        style="object-position: {{ block.settings.focal_point }}"
                      >
                    {%- endif -%}
                  {%- else -%}
                    {%- assign img_url = block.settings.image | img_url: '1x1' | replace: '_1x1.', '_{width}x.' -%}
                    <img
                      class="hero__image hero__image--{{ block.id }} lazyload{% if has_mobile_image %} small--hide{% endif %}"
                      src="{{ block.settings.image | img_url: '300x' }}"
                      data-src="{{ img_url }}"
                      data-aspectratio="{{ block.settings.image.aspect_ratio }}"
                      data-sizes="auto"
                      alt="{{ block.settings.image.alt | escape }}"
                      style="object-position: {{ block.settings.focal_point }}"
                    >
                    {%- if has_mobile_image -%}
                      {%- assign img_url_mobile = block.settings.image_mobile
                        | img_url: '1x1'
                        | replace: '_1x1.', '_{width}x.'
                      -%}
                      <img
                        class="hero__image hero__image--{{ block.id }} lazyload medium-up--hide"
                        src="{{ block.settings.image_mobile | img_url: '300x' }}"
                        data-src="{{ img_url_mobile }}"
                        data-aspectratio="{{ block.settings.image_mobile.aspect_ratio }}"
                        data-sizes="auto"
                        alt="{{ block.settings.image_mobile.alt | escape }}"
                        style="object-position: {{ block.settings.focal_point }}"
                      >
                    {%- endif -%}
                  {%- endif -%}
                  <noscript>
                    <img
                      class="hero__image hero__image--{{ block.id }}"
                      src="{{ block.settings.image | img_url: '1400x' }}"
                      alt="{{ block.settings.image.alt | escape }}"
                    >
                  </noscript>
                {%- else -%}
                  {%- if template == 'password' -%}
                    {%- assign password_image = 'password-page-background.jpg' | asset_url -%}
                    <img class="hero__image lazyload" src="{{ password_image }}">
                  {%- else -%}
                    {{ 'lifestyle-1' | placeholder_svg_tag: 'placeholder-svg' }}
                  {%- endif -%}
                {%- endif -%}
              </div>

              {%- if hero_text -%}
                <div class="hero__text-wrap">
                  <div class="page-width">
                    <div class="hero__text-content {{ block.settings.text_align }}">
                      <div class="hero__text-shadow">
                        {%- unless block.settings.top_subheading == blank -%}
                          <div class="hero__top-subtitle">
                            <div class="hero__animation-contents">
                              {{ block.settings.top_subheading | escape }}
                            </div>
                          </div>
                        {%- endunless -%}
                        {%- unless block.settings.title == blank -%}
                          <h1 class="h1 hero__title" style="color:#FFFFFF">
                            <div class="hero__animation-contents">
                              {{ block.settings.title | strip_html | newline_to_br -}}
                            </div>
                          </h1>
                        {%- endunless -%}
                        {%- if block.settings.subheading or block.settings.link or block.settings.link_2 -%}
                          {%- unless block.settings.subheading == blank -%}
                            <div class="hero__subtitle">
                              <div class="hero__animation-contents">
                                {{ block.settings.subheading | escape }}
                              </div>
                            </div>
                          {%- endunless -%}
                          {% render 'search-bar' %}
                          {%- if block.settings.link_text != blank or block.settings.link_text_2 != blank -%}
                            <div class="hero__link">
                              {%- if block.settings.link_text != blank -%}
                                <a
                                  href="{{ block.settings.link }}"
                                  class="btn{% if block.settings.color_accent contains 'rgba(0,0,0,0)' %} btn--inverse{% endif %}"
                                >
                                  {{ block.settings.link_text }}
                                </a>
                              {%- endif -%}
                              {%- if block.settings.link_text_2 != blank -%}
                                <a
                                  href="{{ block.settings.link_2 }}"
                                  class="btn{% if block.settings.color_accent contains 'rgba(0,0,0,0)' %} btn--inverse{% endif %}"
                                >
                                  {{ block.settings.link_text_2 }}
                                </a>
                              {%- endif -%}
                            </div>
                          {%- endif -%}
                        {%- endif -%}
                      </div>
                    </div>
                  </div>
                </div>
              {%- endif -%}
            </div>
          {%- endfor -%}
        </div>
      </div>
    </div>
  {%- endif -%}

  {%- if section.blocks.size == 0 -%}
    <div class="placeholder-noblocks">
      {{ 'home_page.onboarding.no_content' | t }}
    </div>
  {%- endif -%}
</div>
{%- unless section.settings.full_width -%}
  </div>
{%- endunless -%}

