sections/st2-offre-sofa-tantra.liquid:
{%- comment -%} Landing affiliation sofa-tantra.com (refonte 14-10-2026). Contenu autonome, classes préfixées st2-. {%- endcomment -%}
{%- assign st2_lr = collections['sofa-tantrique'].products_count -%}
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Poppins:wght@400;700&display=swap" rel="stylesheet">
<style>
.st2{
  --rose:#E83F4E;--rose-dark:#C9303E;--ink:#222222;--ink-soft:#5f5f5f;--blanc:#FFFFFF;--creme:#FBF6F2;--rose-pale:#FDF1F2;--border:#EBE5E0;
  --radius-md:8px;--radius-lg:14px;--radius-pill:999px;
  --shadow-sm:0 1px 3px rgba(34,34,34,.06);--shadow-md:0 8px 30px rgba(34,34,34,.08);--shadow-focus:0 0 0 3px rgba(232,63,78,.20);
  font-family:'Poppins',sans-serif;font-weight:400;font-size:16px;line-height:1.6;color:var(--ink);background:var(--blanc);
  container-type:inline-size;container-name:st2;
}
.st2 *{box-sizing:border-box}
.st2 h1,.st2 h2,.st2 h3,.st2 p,.st2 ul,.st2 dl{margin:0}
.st2 h1,.st2 h2,.st2 h3,.st2 .st2-btn,.st2 .st2-kicker,.st2 .st2-price{font-weight:700}
.st2 a{color:inherit}
.st2-wrap{max-width:1100px;margin:0 auto;padding:0 24px}
.st2-kicker{font-size:11px;letter-spacing:.3em;text-transform:uppercase;color:var(--rose)}
.st2-num{font-variant-numeric:tabular-nums}
/* Boutons */
.st2-btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;min-height:52px;padding:0 28px;border-radius:var(--radius-pill);font-size:16px;line-height:1.2;text-decoration:none !important;text-align:center;cursor:pointer;border:2px solid transparent;transition:background .15s ease,color .15s ease,border-color .15s ease}
.st2-btn:focus-visible{outline:none;box-shadow:var(--shadow-focus)}
.st2-btn-primary{background:var(--rose);color:var(--blanc) !important}
.st2-btn-primary:hover{background:var(--rose-dark)}
.st2-btn-secondary{background:transparent;color:var(--rose) !important;border-color:var(--rose)}
.st2-btn-secondary:hover{background:var(--rose);color:var(--blanc) !important}
.st2-copy{display:inline-flex;align-items:center;gap:6px;min-height:44px;padding:0 14px;margin-left:4px;border:1px solid var(--border);border-radius:var(--radius-pill);background:var(--blanc);font:inherit;font-size:14px;font-weight:700;color:var(--ink);cursor:pointer}
.st2-copy:hover{border-color:var(--ink)}
.st2-copy:focus-visible{outline:none;box-shadow:var(--shadow-focus)}
.st2-copy svg{width:16px;height:16px}
/* Hero */
.st2-hero{background:linear-gradient(135deg,#FFFFFF 0%,#FDF1F2 100%);padding:56px 0 48px}
.st2-hero-grid{display:grid;grid-template-columns:minmax(0,1.05fr) minmax(0,1fr);gap:48px;align-items:center}
.st2-hero h1{font-size:clamp(34px,4.6vw,52px);line-height:1.12;letter-spacing:-.01em;margin:14px 0 18px}
.st2-hero h1 em{font-style:normal;color:var(--rose)}
.st2-lead{font-size:18px;color:var(--ink-soft);max-width:34em}
.st2-offer{margin-top:28px;padding:28px;background:#FFFFFF;border:1px solid var(--border);border-radius:14px;box-shadow:0 1px 3px rgba(34,34,34,.06)}
.st2-offer .st2-btn-primary{width:100%}
.st2-offer .st2-prices{margin:6px 0 20px}
.st2-codeline{margin-top:16px !important;line-height:1.5}
.st2-offer-name{font-size:15px;color:var(--ink-soft)}
.st2-offer-name strong{color:var(--ink)}
.st2-prices{display:flex;align-items:baseline;gap:12px;margin:2px 0 18px}
.st2-price{font-size:40px;line-height:1.1}
.st2-was{font-size:18px;color:var(--ink-soft);text-decoration:line-through}
.st2-save{font-size:14px;font-weight:700;color:var(--rose)}
.st2-codeline{margin-top:14px;font-size:14px;color:var(--ink-soft);display:flex;flex-wrap:wrap;align-items:center;gap:4px}
.st2-codeline b{color:var(--ink);letter-spacing:.06em}
.st2-hero-media{position:relative;margin:0}
.st2-hero-media img{display:block;width:100%;height:auto;mix-blend-mode:multiply}
.st2-hero-media figcaption{font-size:13px;color:var(--ink-soft);text-align:center;margin-top:4px}
/* Preuves */
.st2-proof{list-style:none;padding:0;margin:40px 0 0 !important;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;border-top:1px solid var(--border);padding-top:24px !important}
.st2-proof li{display:flex;gap:10px;align-items:flex-start;font-size:14px;line-height:1.45;color:var(--ink-soft)}
.st2-proof li strong{display:block;color:var(--ink)}
.st2-proof svg{flex:0 0 20px;width:20px;height:20px;color:var(--rose);margin-top:1px}
/* Sections */
.st2-lead-m{display:none}
.st2-scenes{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:32px}
.st2-scene{border-top:1px solid var(--ink);padding-top:18px}
.st2-scene-n{font-size:14px;font-weight:700;letter-spacing:.1em;color:var(--rose)}
.st2-scene h3{font-size:22px;line-height:1.25;margin:8px 0 10px}
.st2-scene p:last-child{color:var(--ink-soft)}
.st2-hero-media img.st2-photo{mix-blend-mode:normal;aspect-ratio:1/1;object-fit:cover;border-radius:14px}
.st2-scene-img{display:block;width:100%;height:auto;aspect-ratio:4/3;object-fit:cover;border-radius:14px;margin-bottom:18px}
.st2-final img.st2-photo{mix-blend-mode:normal;aspect-ratio:4/3;object-fit:cover;border-radius:14px}
.st2-guide{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:36px 48px;max-width:980px}
.st2-guide-item h3{font-size:20px;line-height:1.3;margin-bottom:10px}
.st2-guide-item p{color:var(--ink-soft)}
.st2-guide a,.st2-more a{color:var(--ink);text-decoration:underline;text-underline-offset:3px;text-decoration-color:var(--rose)}
.st2-guide a:hover,.st2-more a:hover{color:var(--rose)}
.st2-more{margin-top:32px;font-size:14px;color:var(--ink-soft);max-width:980px}
.st2-card-hover{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;opacity:0;transition:opacity .35s ease;pointer-events:none}
@media (hover:hover){.st2-card:hover .st2-card-hover,.st2-card:focus-within .st2-card-hover{opacity:1}}
.st2-sec{padding:72px 0}
.st2-sec-creme{background:var(--creme)}
.st2-head{max-width:640px;margin-bottom:36px}
.st2-head h2{font-size:clamp(26px,3.2vw,36px);line-height:1.2;margin-top:10px}
.st2-head p{color:var(--ink-soft);margin-top:10px}
/* Cartes modèles */
.st2-cards{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:20px}
.st2-card{display:flex;flex-direction:column;background:var(--blanc);border:1px solid var(--border);border-radius:var(--radius-lg);overflow:hidden;transition:box-shadow .25s ease}
.st2-card:hover{box-shadow:var(--shadow-md)}
.st2-card.is-pick{border-color:var(--ink)}
.st2-card-img{position:relative;aspect-ratio:1/1;background:var(--blanc)}
.st2-card-img img{width:100%;height:100%;object-fit:contain;display:block}
.st2-tag{position:absolute;z-index:2;top:12px;left:12px;background:var(--ink);color:var(--blanc);font-size:12px;font-weight:700;padding:4px 10px;border-radius:var(--radius-pill)}
.st2-card-body{display:flex;flex-direction:column;flex:1;padding:18px 18px 20px;border-top:1px solid var(--border)}
.st2-card h3{font-size:18px;line-height:1.3}
.st2-card-pitch{font-size:14px;color:var(--ink-soft);margin-top:6px}
.st2-specs{display:grid;grid-template-columns:auto 1fr;gap:4px 12px;font-size:13px;margin:14px 0 16px !important}
.st2-specs dt{color:var(--ink-soft)}
.st2-specs dd{margin:0;text-align:right}
.st2-card-foot{margin-top:auto}
.st2-card .st2-prices{margin:0 0 14px}
.st2-card .st2-price{font-size:26px}
.st2-card .st2-was{font-size:15px}
.st2-card .st2-btn{width:100%;min-height:48px;padding:0 16px;font-size:15px}
.st2-note{font-size:13px;color:var(--ink-soft);margin-top:20px !important}
/* Pourquoi */
.st2-why{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}
.st2-why-item{position:relative;background:var(--blanc);border:1px solid var(--border);border-radius:var(--radius-lg);padding:28px 24px 24px;overflow:hidden}
.st2-why-item::before{content:attr(data-num);position:absolute;top:-4px;right:14px;font-size:56px;font-weight:700;line-height:1;color:var(--creme)}
.st2-why-item h3{position:relative;padding-right:56px;font-size:18px;line-height:1.3}
.st2-why-item p{position:relative;font-size:15px;color:var(--ink-soft);margin-top:8px}
/* FAQ */
.st2-faq{max-width:760px}
.st2-faq details{border-bottom:1px solid var(--border)}
.st2-faq details:first-child{border-top:1px solid var(--border)}
.st2-faq summary{list-style:none;cursor:pointer;display:flex;justify-content:space-between;align-items:center;gap:16px;min-height:56px;padding:14px 0;font-weight:700}
.st2-faq summary::-webkit-details-marker{display:none}
.st2-faq summary:focus-visible{outline:none;box-shadow:var(--shadow-focus);border-radius:var(--radius-md)}
.st2-faq summary svg{flex:0 0 20px;width:20px;height:20px;transition:transform .25s ease}
.st2-faq details[open] summary svg{transform:rotate(45deg)}
.st2-faq details p{padding:0 0 18px;color:var(--ink-soft);max-width:65ch}
/* Final */
.st2-final{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.2fr);gap:40px;align-items:center}
.st2-final img{display:block;width:100%;height:auto;mix-blend-mode:multiply}
.st2-final h2{font-size:clamp(26px,3.2vw,36px);line-height:1.2;margin:10px 0 8px}
.st2-final .st2-prices{margin:8px 0 20px}
.st2-alt{display:inline-flex;align-items:center;min-height:44px;margin-top:6px;font-size:14px;color:var(--ink-soft) !important}
.st2-disclose{font-size:12px;color:var(--ink-soft);margin-top:40px !important;max-width:760px}
/* Barre mobile */
.st2-bar{position:fixed;left:0;right:0;bottom:0;z-index:40;display:none;align-items:center;justify-content:space-between;gap:12px;padding:10px 16px calc(10px + env(safe-area-inset-bottom));background:rgba(255,255,255,.96);border-top:1px solid var(--border);box-shadow:0 -4px 20px rgba(34,34,34,.06);transform:translateY(110%);transition:transform .25s ease}
.st2-bar.is-on{transform:none}
.st2-bar-txt{font-size:13px;line-height:1.3;color:var(--ink-soft)}
.st2-bar-txt strong{display:block;font-size:17px;color:var(--ink)}
.st2-bar .st2-was{font-size:13px;font-weight:400;margin-left:4px}
.st2-bar .st2-btn{min-height:48px;padding:0 20px;font-size:15px;flex:0 0 auto}
.st2-sr{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}
@container st2 (max-width:900px){
  .st2-cards{grid-template-columns:repeat(2,minmax(0,1fr))}
  .st2-proof{grid-template-columns:repeat(2,minmax(0,1fr))}
}
