templates/customers/account.liquid:
{%  style %}
.beta_container{
  border:solid 1px #000;
  padding: 20px;
  margin:20px;
  border-radius:15px;
}
.account_sidebar{
  background:#F7F7F7;
  border:solid 1px #F7F7F7;
  border-radius:20px;
  padding:20px
}
  .account_content{
  padding:20px
}
  .customer_room-listing--item{
    display:flex;justify-content:space-between;align-items:center;
    padding:10px 
  }
  .customer_room-listing--item:nth-child(odd){
    background:#F7F7F7
  }
  .customer_room-listing--item:th-child(even){
    background:#FFF
  }
  .customer_room-listing--title{}
  .customer_room-listing--edit{}
  {%  endstyle %}
{%- paginate customer.orders by 20 -%}
  <div class="page-width page-content">
    <div class="beta_container">
        <h4></strong>Cette section est en phase de test / construction.</H4>
        Si vous constatez des erreurs dans la mise à jour de votre fiche ou si vous souhaitez d'autres informations, veuillez nous contacter.<br>
        Si vous avez plusieurs rooms listées sur Love'nSpa, contactez-nous.<br>

        </div>
    <header class="section-header section-header--with-link">
      <h1 class="section-header__title text-center">
        {{ 'customer.account.title' | t }}
      </h1>
      <a href="{{ routes.account_logout_url }}" class="section-header__link">{{ 'layout.customer.log_out' | t }}</a>
    </header>

    <div class="grid">
      <div class="grid__item medium-up--one-quarter account_sidebar">
<ul>
  <li>Mes informations</li>
  <li>Mes rooms</li>
  <li>Mes abonnements</li>
  <li>Mes commandes</li>
</ul>

      </div>
      <div class="grid__item medium-up--three-quarters account_content">
        <h2>Mes informations</h2>
        <ul>
          <li><strong>Prénom : </strong>{{ customer.first_name }}</li>
          <li><strong>Nom: </strong>{{ customer.last_name }}</li>
          <li><strong>Adresse email : </strong>{{ customer.email }}</li>
          <li><strong>Téléphone : </strong>{{ customer.phone }}</li>
          <li><strong>Société : </strong>{{ customer.current_company }}</li>
        </ul>
        <h2>Mes rooms</h2>


        {%- capture uniqueRooms -%}
        {% assign seen_titles = "" %}
          <ul class="customer_room-listing">
        {%- for order in customer.orders -%}
          {%- for line_item in order.line_items -%}
            {%- unless seen_titles contains line_item.title -%}
              {% assign seen_titles = seen_titles | append: line_item.title | append: "," %}
              <li class="customer_room-listing--item">
                <div class="customer_room-listing--title">
                <a href="{{ line_item.product.url }}" target="_blank">
                  {{ line_item.title }}  
                  <svg id="Layer_1" enable-background="new 0 0 24 24" height="20" viewBox="0 0 24 24" width="20" xmlns="http://www.w3.org/2000/svg"><g><path d="m18 20h-12c-1.1 0-2-.9-2-2v-12c0-1.1.9-2 2-2h4c.6 0 1 .4 1 1s-.4 1-1 1h-4v12h12v-4c0-.6.4-1 1-1s1 .4 1 1v4c0 1.1-.9 2-2 2z"/></g><g><path d="m20 10c-.6 0-1-.4-1-1v-4h-4c-.6 0-1-.4-1-1s.4-1 1-1h5c.6 0 1 .4 1 1v5c0 .6-.4 1-1 1z"/></g><g><path d="m13 12c-.3 0-.5-.1-.7-.3-.4-.4-.4-1 0-1.4l7-7c.4-.4 1-.4 1.4 0s.4 1 0 1.4l-7 7c-.2.2-.4.3-.7.3z"/></g></svg>              
                </a>
              </div>
                <div class="customer_room-listing--edit"><a href="/pages/formulaire-modification-de-room?room_id={{ line_item.product.id }}">Modifier</a></div>
              </li>
            {%- endunless -%}
          {%- endfor -%}
        {%- endfor -%}
          </ul>
        {%- endcapture -%}

        {{ uniqueRooms }}


        <h2>Mes commandes</h2>
         {%- if customer.orders.size != 0 -%}
          <table class="table--responsive table--small-text">
            <thead>
              <tr>
                <th>{{ 'customer.orders.order_number' | t }}</th>
                <th>{{ 'customer.orders.date' | t }}</th>
                <th>{{ 'customer.orders.payment_status' | t }}</th>
                <th>{{ 'customer.orders.fulfillment_status' | t }}</th>
                <th>{{ 'customer.orders.total' | t }}</th>
              </tr>
            </thead>
            <tbody>
              {%- for order in customer.orders -%}
                <tr class="table__section">
                  <td data-label="{{ 'customer.orders.order_number' | t }}">
                    {{ order.name | link_to: order.customer_url }}
                  </td>
                  <td data-label="{{ 'customer.orders.date' | t }}">
                    {{ order.created_at | time_tag: format: 'date' }}
                  </td>
                  <td data-label="{{ 'customer.orders.payment_status' | t }}">{{ order.financial_status_label }}</td>
                  <td data-label="{{ 'customer.orders.fulfillment_status' | t }}">
                    {{ order.fulfillment_status_label }}
                  </td>
                  <td data-label="{{ 'customer.orders.total' | t }}">{{ order.total_price | money }}</td>
                </tr>
              {%- endfor -%}
            </tbody>
          </table>

          <hr class="hr--clear">

        {%- else -%}
          <p>{{ 'customer.orders.none' | t }}</p>
        {%- endif -%}


      </div>


    </div>

    {%- liquid
      if paginate.pages > 1
        render 'pagination', paginate: paginate
      endif
    -%}
  </div>
{%- endpaginate -%}

templates/gift_card.liquid:
{% layout 'gift_card' %}

{%- assign formatted_initial_value = gift_card.initial_value | money_without_trailing_zeros: gift_card.currency -%}

<div class="giftcard__border{% if gift_card.expired or gift_card.enabled != true %} disabled{% endif %}">
  <div class="giftcard__content">

    <div class="giftcard__header">
      <h2 class="h4 giftcard__title">{{ 'gift_cards.issued.subtext' | t }}</h2>
      {% unless gift_card.enabled %}
        <span class="giftcard__tag">{{ 'gift_cards.issued.disabled' | t }}</span>
      {% endunless %}
      {%- assign gift_card_expiry_date = gift_card.expires_on | date: "%d/%m/%y" -%}
      {% if gift_card.expired and gift_card.enabled %}
         <span class="giftcard__tag">{{ 'gift_cards.issued.expired' | t: expiry: gift_card_expiry_date }}</span>
      {% endif %}
      {% if gift_card.expired != true and gift_card.expires_on and gift_card.enabled %}
        <span class="giftcard__tag giftcard__tag--active">{{ 'gift_cards.issued.active' | t: expiry: gift_card_expiry_date }}</span>
      {% endif %}
    </div>

    <div class="giftcard__wrap">
      <img src="{{ 'gift-card/card.jpg' | shopify_asset_url }}" alt="Gift card illustration">

      {%- assign initial_value_size = formatted_initial_value | size -%}
      <div class="h1 giftcard__amount{% if initial_value_size > 6 %} giftcard__amount--medium{% endif %}">
        {% if gift_card.balance != gift_card.initial_value %}
          <span class="tooltip">
            <span class="tooltip__label">{{ gift_card.balance | money }} <small>left</small></span>
          </span>
        {% endif %}
        <strong>{{ formatted_initial_value }}</strong>
      </div>

      {%- assign code_size = gift_card.code | format_code | size -%}
      <div class="giftcard__code{% if code_size <= 25 %} giftcard__code--large{% elsif code_size > 25 and code_size <= 30 %} giftcard__code--medium{% else %} giftcard__code--small{% endif %}" onclick="selectText('GiftCardDigits');">
        <div class="giftcard__code__inner">
          <strong class="giftcard__code__text" id="GiftCardDigits">{{ gift_card.code | format_code }}</strong>
        </div>
      </div>
    </div>

    <p class="giftcard__instructions">
      {{ 'gift_cards.issued.redeem' | t }}
    </p>

    <div id="QrCode"></div>
    <script>
      new QRCode(document.getElementById('QrCode'), {
        text: "{{ gift_card.qr_identifier }}",
        width: 120,
        height: 120
      });
    </script>

    <div class="giftcard__actions">
      <a href="{{ shop.url }}" class="btn" target="_blank">{{ 'gift_cards.issued.shop_link' | t }}</a>
      <a href="#" class="action-link" onclick="window.print();">
        <i class="action-link__print"></i>{{ 'gift_cards.issued.print' | t }}
      </a>
    </div>

  </div>
</div>

<script type="text/javascript">
  /*============================================================================
    Auto-select gift card code on click, based on ID passed to the function
      - Use a different method depending on IE or others
  ==============================================================================*/
  function selectText(element) {
    var doc = document,
        text = doc.getElementById(element);

    if (doc.body.createTextRange) { // ms
      var range = doc.body.createTextRange();
      range.moveToElementText(text);
      range.select();
    } else if (window.getSelection) { // moz, opera, webkit
      var selection = window.getSelection(),
          range = doc.createRange();
      range.selectNodeContents(text);
      selection.removeAllRanges();
      selection.addRange(range);
    }
  }
</script>
</html>

