templates/search.facets.liquid:
{% layout none %}
{%- comment -%}
  Même flux que collection.facets pour /search?view=facets&q=…&filter.* :
  handles des produits du résultat de recherche filtré (paginate 250).
{%- endcomment -%}
{%- if search.performed -%}
  {%- paginate search.results by 250 -%}
{"page":{{ paginate.current_page | json }},"pages":{{ paginate.pages | json }},"count":{{ search.results_count | json }},"handles":[
{%- assign loven_first = true -%}
{%- for item in search.results -%}
  {%- if item.object_type == 'product' -%}
    {%- unless loven_first -%},{%- endunless -%}{%- assign loven_first = false -%}{{ item.handle | json }}
  {%- endif -%}
{%- endfor -%}
]}
  {%- endpaginate -%}
{%- else -%}
{"page":1,"pages":1,"count":0,"handles":[]}
{%- endif -%}

