templates/search.markers.liquid:
{% layout none %}
{%- comment -%}
  Même payload léger que collection.markers, pour /search?view=markers.
  Plafond Shopify 250 par page de ce flux, pas 48 fiches.
{%- endcomment -%}
{%- if search.performed -%}
  {%- paginate search.results by 250 -%}
  {%- capture loven_marker_locations -%}
  [
    {%- assign loc_first = true -%}
    {%- for item in search.results -%}
      {%- if item.object_type == 'product' -%}
        {%- assign product = item -%}
        {%- comment -%} Coordonnées : custom.* (ordre naturel), repli accentuate.* croisé. Migration 15/10/2026. {%- endcomment -%}
        {%- assign loc_lat = product.metafields.custom.latitude.value | append: '' | default: product.metafields.accentuate.longitude -%}
        {%- assign loc_lon = product.metafields.custom.longitude.value | append: '' | default: product.metafields.accentuate.latitude -%}
        {%- if loc_lat != blank or loc_lon != blank -%}
          {%- unless loc_first -%},{%- endunless -%}
          {%- assign loc_first = false -%}
          {
            "lat": {{ loc_lat | json }},
            "lon": {{ loc_lon | json }},
            "title": {{ product.title | json }},
            "price": {{ product.price | money | json }},
            "thumbnail": {% if product.featured_image != blank %}{{ product.featured_image | image_url: width: 400 | json }}{% else %}""{% endif %},
            "id": {{ product.id | json }},
            "url": {{ shop.url | append: product.url | json }},
            "handle": {{ product.handle | json }},
            "productType": {{ product.type | json }},
            "region": {{ product.metafields.accentuate.region | json }},
            "ville": {{ product.metafields.accentuate.ville | json }},
            "embedUrl": {% if product.metafields.accentuate.ical_id != blank %}{{ product.metafields.accentuate.ical_id | json }}{% else %}""{% endif %}
          }
        {%- endif -%}
      {%- endif -%}
    {%- endfor -%}
  ]
  {%- endcapture -%}
  {"page":{{ paginate.current_page | json }},"pages":{{ paginate.pages | json }},"locations":{{ loven_marker_locations }}}
  {%- endpaginate -%}
{%- else -%}
{"page":1,"pages":1,"locations":[]}
{%- endif -%}

templates/search.recently-viewed.liquid:
{% comment %}
  Template used to generated recently viewed product section
{% endcomment %}
{% layout none %}

{%- if search.performed -%}

  <div class="new-grid product-grid scrollable-grid--small" data-view="scrollable-7">
    {%- for item in search.results -%}
      {%- if item.object_type == 'product' -%}
        {%- liquid
          render 'product-grid-item', product: item

          if settings.quick_shop_enable
            render 'quick-shop-modal', product: item
          endif
        -%}
      {%- endif -%}
    {%- endfor -%}
  </div>

{%- endif -%}
